    console.error('Error:', {
      name: err.name,
      message: err.message,
      stack: err.stack,
      details: err.details,
    });
  }

  res.status(status).json({
    error: {
      message: err.message || 'Internal Server Error',
      ...(err.details && !isProd ? { details: err.details } : {}),
    },
  });
});

