function normalizeChain(chain) {
  const c = String(chain || '').trim().toLowerCase();

  // Common alias mapping
  switch (c) {
    case 'eth':
    case 'ethereum mainnet':
    case 'mainnet':
      return 'ethereum';
    case 'matic':
    case 'polygon pos':
      return 'polygon';
    case 'arb':
      return 'arbitrum';
    case 'op':
      return 'optimism';
    case 'bsc':
    case 'bnb':
    case 'binance smart chain':
      return 'bsc';
    case 'avax':
    case 'avalanche c-chain':
      return 'avalanche';
    case 'sol':
      return 'solana';
    case 'base mainnet':
      return 'base';
    default:
      return c || 'unknown';
  }
}

/**
 * Normalize status strings into a canonical lowercased form.
 */
function normalizeStatus(status) {
  const s = String(status || '').trim().toLowerCase();
  const synonyms = new Map([
    ['live', 'live'],
    ['active', 'live'],
    ['open', 'live'],
    ['claimable', 'live'],
    ['available', 'available'],
    ['upcoming', 'upcoming'],
    ['soon', 'upcoming'],
    ['scheduled', 'upcoming'],
    ['ended', 'ended'],
    ['finished', 'ended'],
    ['closed', 'ended'],
    ['unknown', 'unknown']
  ]);
  return synonyms.get(s) || s || 'unknown';
}

