/**
 * Adds +/- 20% jitter to backoff to avoid thundering herd.
 * @param {number} value
 */
function withJitter(value) {
  const jitter = value * 0.2;
  return Math.floor(value + (Math.random() * jitter * 2 - jitter));
}

/**
