  if (!contentType.includes("application/json")) {
    const text = await res.text();
    const err = new Error(`Unexpected content-type: ${contentType || "unknown"}`);
    // Attach for diagnostics
    // @ts-ignore
    err.responseBody = text;
    // @ts-ignore
    err.status = res.status;
    throw err;
  }
  return res.json();
}

/**
