      throw new Error("stakingContractAddress is required and must be a valid address");
    }
    if (!config.stakingTokenAddress || !ethers.isAddress(config.stakingTokenAddress)) {
      throw new Error("stakingTokenAddress is required and must be a valid address");
    }
    if (!config.stakingContractAbi || !Array.isArray(config.stakingContractAbi)) {
      // We allow missing ABI only if the generic ABI is used by default. Enforce array type.
      // Fallback ABI is provided during normalization.
    }
  }

  private static requireEnv(key: string): string {
    const val = process.env[key];
    if (!val) throw new Error(`Missing required environment variable: ${key}`);
    return val;
  }

  // Returns the connected signer (throws if missing).
  private requireSigner(): ethers.Wallet {
    if (!this.signer) {
      throw new Error("No signer configured. Provide a privateKey to perform write operations.");
    }
    return this.signer;
  }

  // Fetch token info and cache it to avoid repeated calls.
  async getTokenInfo(): Promise<TokenInfo> {
    if (this.tokenInfoCache) return this.tokenInfoCache;

    const [name, symbol, decimals] = await Promise.all([
      this.tokenContract.name().catch(() => "Unknown"),
      this.tokenContract.symbol().catch(() => "TKN"),
      this.tokenContract.decimals().catch(() => 18)
    ]);

    this.tokenInfoCache = {
      name,
      symbol,
      decimals: Number(decimals),
      address: this.cfg.stakingTokenAddress
    };
    return this.tokenInfoCache;
  }

  // Returns the wallet address of the signer (throws if signer not configured).
  async getSignerAddress(): Promise<HexAddress> {
    const signer = this.requireSigner();
    const addr = await signer.getAddress();
    return ethers.getAddress(addr) as HexAddress;
  }

  // Returns the staked balance for a given address (defaults to signer's address).
  async getStakedBalance(address?: HexAddress): Promise<bigint> {
    const acct = address ?? (await this.getSignerAddress());
    return await this.stakingContract.balanceOf(acct);
  }

  // Returns the pending rewards for a given address (defaults to signer's address).
  async getPendingRewards(address?: HexAddress): Promise<bigint> {
    const acct = address ?? (await this.getSignerAddress());
    // Function name is commonly "earned"; confirm against actual contract ABI.
    return await this.stakingContract.earned(acct);
  }

  // Returns the ERC-20 token balance for a given address (defaults to signer's address).
  async getTokenBalance(address?: HexAddress): Promise<bigint> {
    const acct = address ?? (await this.getSignerAddress());
    return await this.tokenContract.balanceOf(acct);
  }

  // Returns the current allowance from owner to the staking contract.
  async getAllowance(owner?: HexAddress): Promise<bigint> {
    const acct = owner ?? (await this.getSignerAddress());
    return await this.tokenContract.allowance(acct, this.cfg.stakingContractAddress);
  }

  // Approves the staking contract to spend at least "required" tokens if needed.
  // Uses the maximum uint256 for broad allowance by default to reduce future approvals.
  async approveIfNeeded(required: bigint, opts?: StakeOptions): Promise<ApproveIfNeededResult> {
    const owner = await this.getSignerAddress();
    const current = await this.getAllowance(owner);

    if (current >= required) {
      return { approved: true, allowance: current, required };
    }

    const signer = this.requireSigner();

    const maxUint = (2n ** 256n) - 1n;
    const approveAmount = maxUint;

    const overrides = await this.prepareGasOverrides(opts?.gas);

    // Estimate gas with buffer
    const est = await this.tokenContract.estimateGas.approve(this.cfg.stakingContractAddress, approveAmount).catch(() => null);
    const gasLimit = this.applyGasBuffer(est ?? 100000n); // fallback reasonable default

    const tx = await this.tokenContract.connect(signer).approve(
      this.cfg.stakingContractAddress,
      approveAmount,
      { ...overrides, gasLimit }
    );

    if (!opts?.skipWaitForReceipt) {
      await tx.wait();
    }

    // Re-fetch allowance to confirm
    const updated = await this.getAllowance(owner);

    return {
      approved: updated >= required,
      allowance: updated,
      required,
      transactionHash: tx.hash
    };
  }

  // Stakes the specified amount of tokens.
  // - amount can be in human-readable units (e.g., "1.5") via stakeHuman
  async stake(amount: bigint, opts?: StakeOptions): Promise<string> {
    const signer = this.requireSigner();

    // Ensure approval
    await this.approveIfNeeded(amount, opts);

    const overrides = await this.prepareGasOverrides(opts?.gas);

    // Estimate gas and add buffer
    const est = await this.stakingContract.estimateGas.stake(amount).catch(() => null);
    const gasLimit = this.applyGasBuffer(est ?? 250000n);

    const tx = await this.stakingContract.connect(signer).stake(amount, { ...overrides, gasLimit });

    if (!opts?.skipWaitForReceipt) {
      await tx.wait();
    }

    return tx.hash;
  }

  // Unstakes the specified amount of tokens.
  async unstake(amount: bigint, opts?: StakeOptions): Promise<string> {
    const signer = this.requireSigner();
    const overrides = await this.prepareGasOverrides(opts?.gas);

    const est = await this.stakingContract.estimateGas.withdraw(amount).catch(() => null);
    const gasLimit = this.applyGasBuffer(est ?? 250000n);

    const tx = await this.stakingContract.connect(signer).withdraw(amount, { ...overrides, gasLimit });

    if (!opts?.skipWaitForReceipt) {
      await tx.wait();
    }

    return tx.hash;
  }

  // Claims staking rewards.
  async claimRewards(opts?: StakeOptions): Promise<string> {
    const signer = this.requireSigner();
    const overrides = await this.prepareGasOverrides(opts?.gas);

    const est = await this.stakingContract.estimateGas.getReward().catch(() => null);
    const gasLimit = this.applyGasBuffer(est ?? 200000n);

    const tx = await this.stakingContract.connect(signer).getReward({ ...overrides, gasLimit });

    if (!opts?.skipWaitForReceipt) {
      await tx.wait();
    }

    return tx.hash;
  }

  // Helper to perform a complete stake flow using a human-readable string amount, e.g., "1.25".
  async stakeHuman(humanAmount: string, opts?: StakeOptions): Promise<string> {
    const amount = await this.parseAmount(humanAmount);
    return this.stake(amount, opts);
  }

  // Helper to format a raw amount (wei-like) into human-readable units.
  async formatAmount(amount: bigint): Promise<string> {
    const token = await this.getTokenInfo();
    return ethers.formatUnits(amount, token.decimals);
  }

  // Parses a human-readable token amount (e.g., "1.5") into base units using token decimals.
  async parseAmount(human: string | number | bigint): Promise<bigint> {
    if (typeof human === "bigint") return human;
    const token = await this.getTokenInfo();
    return ethers.parseUnits(String(human), token.decimals);
  }

  // Subscribes to RewardPaid events and invokes the callback on new events.
  // Returns a function to unsubscribe.
  onRewardPaid(callback: (event: RewardPaidEvent) => void): Unsubscribe {
    const handler = (user: string, amount: bigint, event: ethers.Log) => {
      try {
        callback({
          user: ethers.getAddress(user) as HexAddress,
          amount,
          blockNumber: event.blockNumber ?? 0,
          txHash: event.transactionHash ?? ""
        });
      } catch {
        // Swallow callback errors to avoid unhandled exceptions in event loop
      }
    };

    this.stakingContract.on("RewardPaid", handler);

    return () => {
      this.stakingContract.off("RewardPaid", handler);
    };
  }

  // Prepares gas overrides combining user-provided overrides with provider fee data.
  private async prepareGasOverrides(gas?: GasOverrides): Promise<GasOverrides> {
    const fee = await this.provider.getFeeData();

    // Use user-provided overrides if present, otherwise infer from provider
    const maxPriorityFeePerGas = gas?.maxPriorityFeePerGas ?? fee.maxPriorityFeePerGas ?? undefined;
    const maxFeePerGas = gas?.maxFeePerGas ?? fee.maxFeePerGas ?? fee.gasPrice ?? undefined;

    return {
      maxFeePerGas,
      maxPriorityFeePerGas,
      gasLimit: gas?.gasLimit
    };
  }

  // Applies a configurable buffer to the estimated gas limit.
  private applyGasBuffer(estimated: bigint): bigint {
    const multiplier = this.cfg.defaultGasBufferMultiplier;
    if (!multiplier || multiplier <= 1.0) return estimated;

    // Multiply and round up safely
    const buffered = BigInt(Math.ceil(Number(estimated) * multiplier));
    return buffered > estimated ? buffered : estimated;
  }
}


// File: src/index.ts
// Description: Public entry point for the Lounge Staking SDK.
export * from "./types";
export * from "./LoungeStakingClient";
export { ERC20_ABI } from "./abi/erc20";
export { GENERIC_STAKING_ABI } from "./abi/genericStaking";


// File: examples/usage.ts
// Description: Example usage demonstrating how to integrate the Lounge Staking client in an application.
//
// Setup:
//   npm install ethers
//   export LOUNGE_RPC_URL="https://your.rpc.url"
//   export LOUNGE_STAKING_ADDRESS="0xYourStakingContractAddress"
//   export LOUNGE_TOKEN_ADDRESS="0xYourStakingTokenAddress"
//   export PRIVATE_KEY="0xyourprivatekey"  # Required for write operations
//
// Note: Replace GENERIC_STAKING_ABI with Lounge Finance's actual ABI if it differs.

import { LoungeStakingClient, GENERIC_STAKING_ABI } from "../src";

async function main() {
  // Initialize client from environment variables
  const client = LoungeStakingClient.fromEnv({
    // If you already have the specific staking ABI for Lounge Finance, pass it here:
    stakingContractAbi: GENERIC_STAKING_ABI
  });

  // Read-only operations
  const token = await client.getTokenInfo();
  console.log(`Token: ${token.name} (${token.symbol}), Decimals: ${token.decimals}`);

  const addr = await client.getSignerAddress();
  console.log(`Signer: ${addr}`);

  const [walletBal, stakedBal, pending] = await Promise.all([
    client.getTokenBalance(addr),
    client.getStakedBalance(addr),
    client.getPendingRewards(addr)
  ]);

  console.log(`Wallet Balance: ${await client.formatAmount(walletBal)} ${token.symbol}`);
  console.log(`Staked Balance: ${await client.formatAmount(stakedBal)} ${token.symbol}`);
  console.log(`Pending Rewards: ${await client.formatAmount(pending)} ${token.symbol}`);

  // Subscribe to reward events
  const unsubscribe = client.onRewardPaid(async (evt) => {
    console.log(`RewardPaid: user=${evt.user} amount=${await client.formatAmount(evt.amount)} tx=${evt.txHash}`);
  });

  // State-changing operations (stake / claim / unstake)
  // Stake example: stake 1.25 tokens
  const stakeTxHash = await client.stakeHuman("1.25");
  console.log(`Staked 1.25 ${token.symbol}. Tx: ${stakeTxHash}`);

  // Claim rewards
  const claimTx = await client.claimRewards();
  console.log(`Claimed rewards. Tx: ${claimTx}`);

  // Unstake example: unstake 0.5 tokens
  const half = await client.parseAmount("0.5");
  const unstakeTx = await client.unstake(half);
  console.log(`Unstaked 0.5 ${token.symbol}. Tx: ${unstakeTx}`);

  // Cleanup event listener
  unsubscribe();
}

if (require.main === module) {
  // Basic process error handling for production readiness
  main().catch((err) => {
    console.error("Fatal error in staking example:", err);
    process.exitCode = 1;
  });
}

/**
 * Indusur Engines REST API Client
 * --------------------------------
 * Production-ready JavaScript client for fetching Cummins engines and specifications
 * from Indusur's database via a REST API.
 *
 * Requirements:
 * - Node.js 18+ (for built-in fetch and AbortController)
 * - No external dependencies
 *
 * Features:
 * - Configurable base URL and API key (via constructor or environment variables)
 * - Robust error handling with rich HttpError class
 * - Retries with exponential backoff and jitter (handles 429 Retry-After, 5xx, and network errors)
 * - Request timeouts using AbortController
 * - Pagination support and convenient async iterator for auto-pagination
 * - Well-documented JSDoc for IDE intellisense
 * - Clean, maintainable, and production-ready structure
 *
 * Environment variables:
 * - INDUSUR_API_BASE_URL (e.g., https://api.indusur.com/v1)
 * - INDUSUR_API_KEY (Bearer token)
 *
 * Note: Update defaultBaseUrl if needed to match the actual Indusur API.
 */

/* eslint-disable no-console */

/**
 * @typedef {Object} Logger
 * @property {(msg: string, meta?: any) => void} debug
 * @property {(msg: string, meta?: any) => void} info
 * @property {(msg: string, meta?: any) => void} warn
 * @property {(msg: string, meta?: any) => void} error
 */

/**
 * @typedef {Object} Pagination
 * @property {number=} page - Current page number (1-based), if page-based pagination is used.
 * @property {number=} perPage - Items per page.
 * @property {number=} total - Total items available (if provided by API).
 * @property {string=} nextPageToken - Opaque cursor for next page (if cursor-based pagination is used).
 */

/**
 * @typedef {Object} Engine
 * @property {string} id
 * @property {string} model
 * @property {string=} series
 * @property {string=} application - e.g., "Industrial", "Marine", etc.
 * @property {number=} powerKw
 * @property {number=} powerHp
 * @property {number=} torqueNm
 * @property {number=} displacementL
 * @property {string=} fuelType - e.g., "Diesel"
 * @property {string=} emissions - e.g., "Tier 3", "Stage V"
 * @property {string=} status - e.g., "active", "discontinued"
 * @property {string=} createdAt
 * @property {string=} updatedAt
 */

/**
 * @typedef {Object} Specification
 * @property {string} key
 * @property {string|number|boolean|null} value
 * @property {string=} unit
 * @property {string=} category
 */

/**
 * @typedef {Object} ListEnginesParams
 * @property {number=} page - Page number (1-based). Cannot be used with pageToken.
 * @property {number=} perPage - Items per page.
 * @property {string=} pageToken - Cursor for pagination. Cannot be used with page.
 * @property {string=} q - Free-text search
 * @property {string=} model - Filter by model code/name
 * @property {string=} series - Filter by engine series
 * @property {string=} application - e.g., "Industrial", "Marine"
 * @property {string=} fuelType - e.g., "Diesel"
 * @property {string=} emissions - e.g., "Stage V"
 * @property {number=} minPowerKw
 * @property {number=} maxPowerKw
 * @property {number=} minTorqueNm
 * @property {number=} maxTorqueNm
 * @property {string=} sort - e.g., "model:asc", "powerKw:desc"
 */

/**
 * Custom error for HTTP failures with rich context.
 */
class HttpError extends Error {
  /**
   * @param {string} message
   * @param {number} status
   * @param {string} url
   * @param {string} method
   * @param {any} responseBody
   * @param {Headers} headers
   */
  constructor(message, status, url, method, responseBody, headers) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
    this.url = url;
    this.method = method;
    this.responseBody = responseBody;
    this.headers = headers ? Object.fromEntries(headers.entries()) : {};
    Error.captureStackTrace?.(this, HttpError);
  }
}

/**
 * Sleep helper with cancel support via AbortSignal.
 * @param {number} ms
 * @param {AbortSignal=} signal
 * @returns {Promise<void>}
 */
function delay(ms, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    if (signal) {
      const onAbort = () => {
        clearTimeout(t);
        reject(new DOMException('Delay aborted', 'AbortError'));
      };
      if (signal.aborted) {
        clearTimeout(t);
        reject(new DOMException('Delay aborted', 'AbortError'));
      } else {
        signal.addEventListener('abort', onAbort, { once: true });
      }
    }
  });
}

/**
 * Safe logger that falls back to console or no-op.
 * @returns {Logger}
 */
function createDefaultLogger() {
  if (typeof console !== 'undefined') {
    return {
      debug: (m, meta) => console.debug?.(m, meta ?? ''),
      info: (m, meta) => console.info?.(m, meta ?? ''),
      warn: (m, meta) => console.warn?.(m, meta ?? ''),
      error: (m, meta) => console.error?.(m, meta ?? ''),
    };
  }
  return {
    debug: () => {},
    info: () => {},
    warn: () => {},
    error: () => {},
  };
}

/**
 * Redacts sensitive headers for logging.
 * @param {Record<string,string>} headers
 */
function redactHeaders(headers) {
  const out = { ...headers };
  for (const k of Object.keys(out)) {
    if (/authorization|api-key|x-api-key|proxy-authorization/i.test(k)) {
      out[k] = 'REDACTED';
    }
  }
  return out;
}

/**
 * Builds a query string from an object.
 * - Ignores undefined/null values
 * - Arrays become repeated keys: k=v1&k=v2
 * - Objects are JSON-stringified
 * @param {Record<string, any>=} query
 * @returns {string}
 */
function toQueryString(query) {
  if (!query) return '';
  const params = new URLSearchParams();
  for (const [key, val] of Object.entries(query)) {
    if (val === undefined || val === null) continue;
    if (Array.isArray(val)) {
      for (const v of val) {
        if (v !== undefined && v !== null) params.append(key, String(v));
      }
    } else if (typeof val === 'object') {
      params.set(key, JSON.stringify(val));
    } else {
      params.set(key, String(val));
    }
  }
  const qs = params.toString();
  return qs ? `?${qs}` : '';
}

/**
 * Parses Retry-After header to milliseconds.
 * Supports:
 * - Seconds (integer)
 * - HTTP date
 * @param {string} header
 * @param {number} defaultMs
 * @returns {number}
 */
function parseRetryAfterMs(header, defaultMs) {
  if (!header) return defaultMs;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) {
    return Math.max(0, Math.floor(seconds * 1000));
  }
  const dateMs = Date.parse(header);
  if (!Number.isNaN(dateMs)) {
    const ms = dateMs - Date.now();
    return ms > 0 ? ms : defaultMs;
  }
  return defaultMs;
}

/**
 * @typedef {Object} ApiClientOptions
 * @property {string=} baseUrl - Base URL of the Indusur API (e.g., https://api.indusur.com/v1)
 * @property {string=} apiKey - Bearer token for authentication
 * @property {number=} timeoutMs - Per-request timeout in milliseconds (default: 15000)
 * @property {number=} maxRetries - Max number of retry attempts on transient failures (default: 3)
 * @property {Logger=} logger - Logger implementation (default: console-backed)
 * @property {string=} userAgent - Custom user agent identifier
 * @property {(attempt: number, err: Error, waitMs: number)=>void=} onRetry - Hook called before a retry
 * @property {(input: RequestInfo | URL, init?: RequestInit)=>Promise<Response>=} fetchFn - Custom fetch function (tests/mocks)
 */

class IndusurApiClient {
  /**
   * @param {ApiClientOptions=} options
   */
  constructor(options = {}) {
      if (typeof fetch !== 'function') {
        throw new Error('Global fetch is not available. Please use Node.js 18+ or provide a fetchFn.');
      }
      if (typeof AbortController !== 'function') {
        throw new Error('AbortController is not available. Please use Node.js 18+.');
      }

      const defaultBaseUrl = process.env.INDUSUR_API_BASE_URL || 'https://api.indusur.com/v1';
      this.baseUrl = (options.baseUrl || defaultBaseUrl).replace(/\/+$/, '');
      this.apiKey = options.apiKey || process.env.INDUSUR_API_KEY || '';
      this.timeoutMs = Number.isFinite(options.timeoutMs) ? options.timeoutMs : 15000;
      this.maxRetries = Number.isFinite(options.maxRetries) ? options.maxRetries : 3;
      this.logger = options.logger || createDefaultLogger();
      this.userAgent = options.userAgent || 'IndusurEngineClient/1.0 (+https://your-company.example)';
      this.onRetry = typeof options.onRetry === 'function' ? options.onRetry : null;
      this.fetchFn = options.fetchFn || fetch;

      // Sub-clients
      this.engines = new EnginesClient(this);
  }

  /**
   * Low-level HTTP request with retries, timeout, and error handling.
   * @param {'GET'|'POST'|'PUT'|'PATCH'|'DELETE'} method
   * @param {string} path - Path relative to baseUrl, e.g., "/engines"
   * @param {Object=} opts
   * @param {Record<string, any>=} opts.query
   * @param {any=} opts.body
   * @param {Record<string, string>=} opts.headers
   * @param {AbortSignal=} opts.signal
   * @returns {Promise<any>}
   */
  async request(method, path, opts = {}) {
    const maxAttempts = Math.max(0, this.maxRetries) + 1; // initial try + retries
    const { query, body, headers = {}, signal } = opts;

    const url = new URL(this.baseUrl + (path.startsWith('/') ? path : `/${path}`));
    const qs = toQueryString(query);
    const fullUrl = new URL(url.toString() + qs);

    // Prepare base headers
    /** @type {Record<string,string>} */
    const reqHeaders = {
      Accept: 'application/json',
      ...headers,
    };

    // Auth header if provided
    if (this.apiKey) {
      reqHeaders.Authorization = `Bearer ${this.apiKey}`;
    }

    // User-Agent header (Node only). If not allowed (browser), catch and ignore.
    if (this.userAgent) {
      reqHeaders['User-Agent'] = this.userAgent;
      reqHeaders['X-Client'] = this.userAgent; // in case User-Agent is stripped
    }

    // Serialize body if needed
    /** @type {BodyInit | undefined} */
    let payload;
    if (body !== undefined && body !== null) {
      const isFormData = typeof FormData !== 'undefined' && body instanceof FormData;
      const isBlob = typeof Blob !== 'undefined' && body instanceof Blob;
      const isBuffer = typeof Buffer !== 'undefined' && Buffer.isBuffer(body);
      const isStream = typeof body?.pipe === 'function';

      if (isFormData || isBlob || isBuffer || isStream) {
        payload = body;
      } else if (typeof body === 'string') {
        payload = body;
        if (!('Content-Type' in reqHeaders)) reqHeaders['Content-Type'] = 'text/plain; charset=utf-8';
      } else {
        payload = JSON.stringify(body);
        if (!('Content-Type' in reqHeaders)) reqHeaders['Content-Type'] = 'application/json';
      }
    }

    let attempt = 0;
    let lastError = null;

    while (attempt < maxAttempts) {
      attempt += 1;

      const ac = new AbortController();
      const timer = setTimeout(() => ac.abort(), this.timeoutMs);

      // If caller supplies a signal, tie it to our AbortController
      const onAbort = () => ac.abort();
      if (signal) {
        if (signal.aborted) {
          clearTimeout(timer);
          throw new DOMException('Request aborted by caller', 'AbortError');
        }
        signal.addEventListener('abort', onAbort, { once: true });
      }

      try {
        this.logger.debug(
          `HTTP ${method} ${fullUrl.toString()} attempt ${attempt}/${maxAttempts}`,
          { headers: redactHeaders(reqHeaders) }
        );

        const res = await this.fetchFn(fullUrl, {
          method,
          headers: reqHeaders,
          body: payload,
          signal: ac.signal,
        });

        clearTimeout(timer);
        signal?.removeEventListener('abort', onAbort);

        const contentType = res.headers.get('content-type') || '';
        const isJson = contentType.includes('application/json');

        // Successful responses
        if (res.ok) {
          if (res.status === 204) return null;

          let data;
          try {
            data = isJson ? await res.json() : await res.text();
          } catch (parseErr) {
            throw new HttpError(
              `Failed to parse response: ${String(parseErr)}`,
              res.status,
              fullUrl.toString(),
              method,
              null,
              res.headers
            );
          }
          return data;
        }

        // Handle error responses
        let errorBody = null;
        try {
          errorBody = isJson ? await res.json() : await res.text();
        } catch {
          // ignore parse errors for error path; keep body as null
        }

        const httpError = new HttpError(
          `HTTP ${res.status} ${res.statusText} for ${method} ${fullUrl.toString()}`,
          res.status,
          fullUrl.toString(),
          method,
          errorBody,
          res.headers
        );

        // Determine if we should retry
        if (this.shouldRetry(res.status, attempt, maxAttempts)) {
          const waitMs = this.computeBackoffMs(attempt, res.status, res.headers.get('retry-after'));
          this.onRetry?.(attempt, httpError, waitMs);
          this.logger.warn(`Retrying after HTTP error ${res.status} (attempt ${attempt}/${maxAttempts - 1}) in ${waitMs}ms`, {
            status: res.status,
            url: fullUrl.toString(),
          });
          await delay(waitMs, signal);
          continue;
        }

        // No retry - throw
        throw httpError;
      } catch (err) {
        clearTimeout(timer);
        signal?.removeEventListener('abort', onAbort);

        // Abort errors: do not retry
        if (err && (err.name === 'AbortError' || err.name === 'TimeoutError')) {
          throw err;
        }

        lastError = err;

        // Network errors or other transient errors
        if (this.isNetworkError(err) && attempt < maxAttempts) {
          const waitMs = this.computeBackoffMs(attempt, 0, null);
          this.onRetry?.(attempt, err, waitMs);
          this.logger.warn(`Network error, retrying in ${waitMs}ms (attempt ${attempt}/${maxAttempts - 1})`, {
            error: String(err?.message || err),
            url: fullUrl.toString(),
          });
          await delay(waitMs, signal);
          continue;
        }

        // Non-retryable error
        throw err;
      }
    }

    // Exhausted retries
    throw lastError || new Error('Request failed after retries');
  }

  /**
   * Returns true if the request should be retried based on status and attempt.
   * @param {number} status
   * @param {number} attempt
   * @param {number} maxAttempts
   */
  shouldRetry(status, attempt, maxAttempts) {
    if (attempt >= maxAttempts) return false;
    if (status === 429) return true; // rate limited
    if (status >= 500 && status < 600) return true; // server errors
    return false;
  }

  /**
   * Compute backoff delay with exponential growth and jitter.
   * Honors Retry-After for status 429 when present.
   * @param {number} attempt - current attempt number (1-based)
   * @param {number} status - HTTP status code (0 for network)
   * @param {string|null} retryAfterHeader
   * @returns {number} milliseconds to wait
   */
  computeBackoffMs(attempt, status, retryAfterHeader) {
    const base = 250; // ms
    const cap = 15_000; // ms
    const expo = Math.min(cap, base * Math.pow(2, attempt - 1));
    // Full jitter
    let wait = Math.floor(Math.random() * expo);

    if (status === 429 && retryAfterHeader) {
      const ra = parseRetryAfterMs(retryAfterHeader, wait);
      // Cap excessively large Retry-After to a reasonable max (e.g., 60s)
      wait = Math.min(ra, 60_000);
    }

    return wait;
  }

  /**
   * @param {any} err
   */
  isNetworkError(err) {
    if (!err) return false;
    const msg = String(err.message || err);
    // Heuristic for network-like errors
    return (
      err.name === 'FetchError' ||
      /ENOTFOUND|ECONNRESET|ECONNREFUSED|EAI_AGAIN|ETIMEDOUT|NetworkError|network|socket/i.test(msg)
    );
  }
}

