    "coming_soon",
    "trending",
    "top_rated",
    "top_new",
    "popular_new_releases",
    "featured_free",
    "free"
  ];

  const seen = new Set();
  const items = [];

  for (const bucket of buckets) {
    const section = data?.[bucket]?.items;
    if (!Array.isArray(section)) continue;

