/**
 * NodeP0 + Bitcoin "staking" integration using Node.js
 *
 * IMPORTANT
 * - Bitcoin does not support native proof-of-stake. Platforms like "NodeP0" may provide
 *   staking-like yield products secured by sidechains, restaking protocols, or off-chain arrangements.
 * - This code integrates with a hypothetical NodeP0 REST API to:
 *   - Discover pools
 *   - Create a staking position (requires funding a NodeP0-provided deposit address with on-chain BTC)
 *   - Track status
 *   - Request unstake/withdraw
 *
 * This file provides:
 * - Robust REST API client with retries
 * - Bitcoind RPC integration to send BTC to the NodeP0 deposit address
 * - CLI for typical operations
 * - A mock NodeP0 mode for local testing without real network calls
 *
 * Requirements
 * - Node.js v18+
 * - npm i axios yargs dotenv
 *
 * Environment variables (.env or process env)
 * - NODEP0_BASE_URL=...            // e.g., https://api.nodep0.example or "mock" for local mock
 * - NODEP0_API_KEY=...             // API key/token for NodeP0
 * - BITCOIN_NETWORK=mainnet|testnet|regtest (default: testnet)
 * - BITCOIND_RPC_URL=http://127.0.0.1:18443   // Wallet-enabled bitcoind RPC URL
 * - BITCOIND_RPC_USER=...          // bitcoind RPC username
 * - BITCOIND_RPC_PASSWORD=...      // bitcoind RPC password
 * - BITCOIND_WALLET=wallet_name    // optional; default wallet if omitted
 *
 * Usage (examples)
 * - node nodep0-btc-staking.js pools
 * - node nodep0-btc-staking.js stake --poolId p0-btc-1 --amountSats 100000 --ref user123
 * - node nodep0-btc-staking.js status --stakeId st_abc123
 * - node nodep0-btc-staking.js unstake --stakeId st_abc123
 * - node nodep0-btc-staking.js withdraw --stakeId st_abc123 --to bc1q...
 *
 * Notes
 * - For production, use HTTPS, secure secrets, and enable proper observability (metrics, structured logs).
 * - This code is provided as a robust template; adjust endpoints and fields to match NodeP0's actual API.
 */

import 'dotenv/config';
import axios from 'axios';
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';

// ------------------------------- Utilities -------------------------------

/**
 * Sleep for ms
 * @param {number} ms
 * @returns {Promise<void>}
 */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Exponential backoff retry wrapper for async operations
 * @template T
 * @param {() => Promise<T>} fn
 * @param {{retries?: number, baseMs?: number, factor?: number, onRetry?:(err:unknown, attempt:number)=>void}} opts
 * @returns {Promise<T>}
 */
async function withRetry(fn, opts = {}) {
  const retries = Math.max(0, opts.retries ?? 3);
  const baseMs = opts.baseMs ?? 300;
  const factor = opts.factor ?? 2;

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (attempt === retries) break;
      if (opts.onRetry) {
        opts.onRetry(err, attempt + 1);
      }
      const delay = baseMs * Math.pow(factor, attempt);
      await sleep(delay);
    }
  }
  throw lastErr;
}

/**
 * Simple logger with levels
 */
const log = {
  info: (...a) => console.log(new Date().toISOString(), 'INFO ', ...a),
  warn: (...a) => console.warn(new Date().toISOString(), 'WARN ', ...a),
  error: (...a) => console.error(new Date().toISOString(), 'ERROR', ...a),
  debug: (...a) => {
    if (process.env.DEBUG?.toLowerCase() === 'true') {
      console.log(new Date().toISOString(), 'DEBUG', ...a);
    }
  },
};

// ------------------------------- Config -------------------------------

const CONFIG = {
  nodep0BaseUrl: process.env.NODEP0_BASE_URL || 'mock', // "mock" enables local mock API
  nodep0ApiKey: process.env.NODEP0_API_KEY || 'test_api_key',
  bitcoinNetwork: (process.env.BITCOIN_NETWORK || 'testnet').toLowerCase(),
  bitcoind: {
    url: process.env.BITCOIND_RPC_URL,
    user: process.env.BITCOIND_RPC_USER,
    password: process.env.BITCOIND_RPC_PASSWORD,
    wallet: process.env.BITCOIND_WALLET, // optional
  },
};

// ------------------------------- NodeP0 Client -------------------------------

/**
 * NodeP0 REST client
 * Replace endpoint paths/fields with the actual NodeP0 API spec.
 */
class NodeP0Client {
  /**
   * @param {{baseUrl:string, apiKey:string}} opts
   */
  constructor(opts) {
    if (!opts?.baseUrl) throw new Error('NodeP0Client requires baseUrl');
    if (!opts?.apiKey) throw new Error('NodeP0Client requires apiKey');

    this.baseUrl = opts.baseUrl;
    this.apiKey = opts.apiKey;

    this.http = axios.create({
      baseURL: this.baseUrl,
      timeout: 15000,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`,
      },
    });

    this.isMock = this.baseUrl === 'mock';
    if (this.isMock) {
      this.mockStore = {
        pools: [
          {
            id: 'p0-btc-1',
            network: CONFIG.bitcoinNetwork,
            name: 'NodeP0 BTC Yield Pool',
            minStakeSats: 50_000,
            maxStakeSats: 2_000_000_000,
            apyPct: 3.1,
            lockupDays: 7,
            depositKind: 'on-chain',
          },
        ],
        stakes: new Map(), // stakeId -> record
      };
    }
  }

  /**
   * List staking pools
   * @returns {Promise<any[]>}
   */
  async listPools() {
    if (this.isMock) {
      return this.mockStore.pools;
    }
    return withRetry(() => this.http.get('/staking/pools').then(r => r.data), {
      onRetry: (e, a) => log.warn(`Retry listPools (attempt ${a})`, String(e)),
    });
  }

  /**
   * Create a stake intent. Returns stakeId and deposit address you must fund.
   * @param {{poolId:string, amountSats:number, customerRef?:string}} params
   * @returns {Promise<{stakeId:string, depositAddress:string, expiresAt:string}>}
   */
  async createStake(params) {
    if (!params?.poolId || !Number.isFinite(params?.amountSats)) {
      throw new Error('createStake requires poolId and amountSats');
    }
    if (this.isMock) {
      const stakeId = `st_${Math.random().toString(36).slice(2, 10)}`;
      const depositAddress =
        CONFIG.bitcoinNetwork === 'mainnet'
          ? 'bc1qmockaddress0000000000000000000000000000000'
          : 'tb1qmockaddress0000000000000000000000000000000';
      const now = new Date();
      const expiresAt = new Date(now.getTime() + 60 * 60 * 1000).toISOString();
      this.mockStore.stakes.set(stakeId, {
        stakeId,
        poolId: params.poolId,
        amountSats: params.amountSats,
        customerRef: params.customerRef || null,
        depositAddress,
        expiresAt,
        status: 'awaiting_funding',
        fundingTxId: null,
        createdAt: now.toISOString(),
        updatedAt: now.toISOString(),
      });
      return { stakeId, depositAddress, expiresAt };
    }

    return withRetry(
      () =>
        this.http
          .post('/staking/positions', {
            poolId: params.poolId,
            amountSats: params.amountSats,
            customerRef: params.customerRef,
          })
          .then((r) => r.data),
      { onRetry: (e, a) => log.warn(`Retry createStake (attempt ${a})`, String(e)) }
    );
  }

  /**
   * Submit funding txid after sending BTC to deposit address
   * @param {{stakeId: string, txid: string}} params
   * @returns {Promise<{ok:boolean}>}
   */
  async submitFundingTx(params) {
    if (this.isMock) {
      const rec = this.mockStore.stakes.get(params.stakeId);
      if (!rec) throw new Error('Unknown stakeId');
      rec.fundingTxId = params.txid;
      rec.status = 'pending_confirmation';
      rec.updatedAt = new Date().toISOString();
      // Simulate confirmation after 3 seconds
      setTimeout(() => {
        rec.status = 'active';
        rec.updatedAt = new Date().toISOString();
      }, 3000);
      return { ok: true };
    }
    return withRetry(
      () =>
        this.http
          .post(`/staking/positions/${encodeURIComponent(params.stakeId)}/funding`, {
            txid: params.txid,
          })
          .then((r) => r.data),
      { onRetry: (e, a) => log.warn(`Retry submitFundingTx (attempt ${a})`, String(e)) }
    );
  }

  /**
   * Get stake status
   * @param {string} stakeId
   * @returns {Promise<any>}
   */
  async getStakeStatus(stakeId) {
    if (this.isMock) {
      const rec = this.mockStore.stakes.get(stakeId);
      if (!rec) throw new Error('Unknown stakeId');
      return {
        stakeId: rec.stakeId,
        status: rec.status,
        amountSats: rec.amountSats,
        depositAddress: rec.depositAddress,
        fundingTxId: rec.fundingTxId,
        updatedAt: rec.updatedAt,
      };
    }
    return withRetry(
      () => this.http.get(`/staking/positions/${encodeURIComponent(stakeId)}`).then((r) => r.data),
      { onRetry: (e, a) => log.warn(`Retry getStakeStatus (attempt ${a})`, String(e)) }
    );
  }

  /**
   * Request unstake (may trigger unbonding/exit delay)
   * @param {string} stakeId
   * @returns {Promise<{ok:boolean}>}
   */
  async requestUnstake(stakeId) {
    if (this.isMock) {
      const rec = this.mockStore.stakes.get(stakeId);
      if (!rec) throw new Error('Unknown stakeId');
      if (rec.status !== 'active') throw new Error('Stake not active');
      rec.status = 'exiting';
      rec.updatedAt = new Date().toISOString();
      // Simulate exit completion
      setTimeout(() => {
        rec.status = 'exited';
        rec.updatedAt = new Date().toISOString();
      }, 2000);
      return { ok: true };
    }
    return withRetry(
      () =>
        this.http.post(`/staking/positions/${encodeURIComponent(stakeId)}/unstake`).then((r) => r.data),
      { onRetry: (e, a) => log.warn(`Retry requestUnstake (attempt ${a})`, String(e)) }
    );
  }

  /**
   * Withdraw principal + rewards to a BTC address after exit/vesting
   * @param {{stakeId:string, toAddress:string}} params
   * @returns {Promise<{withdrawalId:string, status:string}>}
   */
  async withdraw(params) {
    if (this.isMock) {
      const rec = this.mockStore.stakes.get(params.stakeId);
      if (!rec) throw new Error('Unknown stakeId');
      if (!['exited', 'active'].includes(rec.status)) {
        throw new Error(`Cannot withdraw while status=${rec.status}`);
      }
      const withdrawalId = `wd_${Math.random().toString(36).slice(2, 10)}`;
      rec.status = 'withdrawn';
      rec.updatedAt = new Date().toISOString();
      return { withdrawalId, status: 'processing' };
    }
    return withRetry(
      () =>
        this.http
          .post(`/staking/positions/${encodeURIComponent(params.stakeId)}/withdraw`, {
            toAddress: params.toAddress,
          })
          .then((r) => r.data),
      { onRetry: (e, a) => log.warn(`Retry withdraw (attempt ${a})`, String(e)) }
    );
  }
}

// ------------------------------- Bitcoin RPC -------------------------------

/**
 * Minimal bitcoind RPC client
 * Requires bitcoind started with -rpcwallet=<yourwallet> or pass wallet via env.
 */
class BitcoinRpc {
  /**
   * @param {{url?:string, user?:string, password?:string, wallet?:string}} opts
   */
  constructor(opts = {}) {
    this.url = opts.url;
    this.user = opts.user;
    this.password = opts.password;
    this.wallet = opts.wallet;

    if (!this.url || !this.user || !this.password) {
      log.warn('Bitcoind RPC not fully configured. Some commands will be unavailable.');
    }
  }

  /**
   * @private
   * @param {string} method
   * @param {any[]} params
   * @returns {Promise<any>}
   */
  async call(method, params = []) {
    if (!this.url || !this.user || !this.password) {
      throw new Error('Bitcoind RPC not configured (BITCOIND_RPC_URL/USER/PASSWORD)');
    }

    const endpoint = this.wallet ? `${this.url}/wallet/${encodeURIComponent(this.wallet)}` : this.url;

    const res = await axios.post(
      endpoint,
      { jsonrpc: '1.0', id: Date.now(), method, params },
      {
        timeout: 20000,
        auth: { username: this.user, password: this.password },
        headers: { 'Content-Type': 'application/json' },
      }
    );

    if (res.data?.error) {
      throw new Error(`RPC error: ${JSON.stringify(res.data.error)}`);
    }
    return res.data?.result;
  }

  /**
   * Get current network info
   */
  getNetworkInfo() {
    return withRetry(() => this.call('getnetworkinfo'), {
      onRetry: (e, a) => log.warn(`Retry getnetworkinfo (attempt ${a})`, String(e)),
    });
  }

  /**
   * Get wallet info
   */
  getWalletInfo() {
    return withRetry(() => this.call('getwalletinfo'), {
      onRetry: (e, a) => log.warn(`Retry getwalletinfo (attempt ${a})`, String(e)),
    });
  }

  /**
   * Send to a bitcoin address (uses wallet's coin selection/fees)
   * @param {string} address
   * @param {number} amountBtc - in BTC
   * @param {{comment?:string, subtractFeeFromAmount?:boolean}} [opts]
   * @returns {Promise<string>} txid
   */
  async sendToAddress(address, amountBtc, opts = {}) {
    // sendtoaddress "address" amount "comment" "comment_to" subtractfeefromamount replaceable conf_target "estimate_mode" avoid_reuse fee_rate verbose
    const params = [
      address,
      amountBtc,
      opts.comment || '',
      '', // comment_to (unused)
      opts.subtractFeeFromAmount === true,
    ];
    return withRetry(() => this.call('sendtoaddress', params), {
      onRetry: (e, a) => log.warn(`Retry sendtoaddress (attempt ${a})`, String(e)),
    });
  }

  /**
   * Validate address
   * @param {string} address
   */
  async validateAddress(address) {
    return withRetry(() => this.call('validateaddress', [address]), {
      onRetry: (e, a) => log.warn(`Retry validateaddress (attempt ${a})`, String(e)),
    });
  }
}

// ------------------------------- Orchestrator -------------------------------

/**
 * High-level integration flow
 */
class NodeP0StakingService {
  /**
   * @param {{nodep0:NodeP0Client, btc:BitcoinRpc}} deps
   */
  constructor({ nodep0, btc }) {
    this.nodep0 = nodep0;
    this.btc = btc;
  }

  /**
   * Create a stake, fund it using bitcoind wallet, and register txid
   * @param {{poolId:string, amountSats:number, customerRef?:string}} params
   */
  async createAndFundStake(params) {
    // 1) Create stake intent with NodeP0
    const { stakeId, depositAddress, expiresAt } = await this.nodep0.createStake({
      poolId: params.poolId,
      amountSats: params.amountSats,
      customerRef: params.customerRef,
    });

    log.info(`Stake created: stakeId=${stakeId}`);
    log.info(`Deposit address: ${depositAddress}`);
    log.info(`Expires at: ${expiresAt}`);

    // 2) Validate deposit address looks OK (via bitcoind RPC validateaddress if available)
    if (this.btc.url) {
      const v = await this.btc.validateAddress(depositAddress);
      if (!v?.isvalid) {
        throw new Error('NodeP0 returned an invalid deposit address');
      }
      // Optional: enforce network checks (testnet/mainnet) based on v.isscript, v.iswitness, etc.
    } else {
      log.warn('Skipping address validation (bitcoind RPC not configured)');
    }

    // 3) Fund: convert sats to BTC and send using wallet
    if (!this.btc.url) {
      if (this.nodep0.isMock) {
        // In mock mode, we simulate a funding txid for demo purposes
        const fakeTxId = `mocktx_${Math.random().toString(36).slice(2, 14)}`;
        log.info(`Simulating funding with fake txid: ${fakeTxId}`);
        await this.nodep0.submitFundingTx({ stakeId, txid: fakeTxId });
        return { stakeId, depositAddress, expiresAt, txid: fakeTxId };
      }
      throw new Error(
        'Bitcoind RPC not configured. Set BITCOIND_RPC_URL/USER/PASSWORD to send funding transaction.'
      );
    }

    const amountBtc = params.amountSats / 1e8;

    log.info(`Sending ${amountBtc} BTC to NodeP0 deposit address...`);
    const txid = await this.btc.sendToAddress(depositAddress, amountBtc, {
      comment: `NodeP0 stake ${stakeId}`,
      subtractFeeFromAmount: false,
    });
    log.info(`Funding txid: ${txid}`);

    // 4) Notify NodeP0 of funding tx
    await this.nodep0.submitFundingTx({ stakeId, txid });

    return { stakeId, depositAddress, expiresAt, txid };
  }
}

// ------------------------------- CLI -------------------------------

/**
 * CLI entrypoint
 */
async function main() {
  const argv = await yargs(hideBin(process.argv))
    .command('pools', 'List available NodeP0 Bitcoin staking pools')
    .command('stake', 'Create a stake and fund it', (y) =>
      y
        .option('poolId', { type: 'string', demandOption: true, desc: 'Pool ID to stake into' })
        .option('amountSats', { type: 'number', demandOption: true, desc: 'Amount in sats' })
        .option('ref', { type: 'string', demandOption: false, desc: 'Customer reference' })
    )
    .command('status', 'Get status of a stake', (y) =>
      y.option('stakeId', { type: 'string', demandOption: true, desc: 'Stake ID' })
    )
    .command('unstake', 'Request unstake for a position', (y) =>
      y.option('stakeId', { type: 'string', demandOption: true, desc: 'Stake ID' })
    )
    .command('withdraw', 'Withdraw principal + rewards', (y) =>
      y
        .option('stakeId', { type: 'string', demandOption: true, desc: 'Stake ID' })
        .option('to', { type: 'string', demandOption: true, desc: 'Destination BTC address' })
    )
    .option('debug', { type: 'boolean', desc: 'Enable debug logs' })
    .demandCommand(1)
    .help().argv;

  if (argv.debug) {
    process.env.DEBUG = 'true';
  }

  const nodep0 = new NodeP0Client({
    baseUrl: CONFIG.nodep0BaseUrl,
    apiKey: CONFIG.nodep0ApiKey,
  });

  const btc = new BitcoinRpc({
    url: CONFIG.bitcoind.url,
    user: CONFIG.bitcoind.user,
    password: CONFIG.bitcoind.password,
    wallet: CONFIG.bitcoind.wallet,
  });

  const svc = new NodeP0StakingService({ nodep0, btc });

  const cmd = argv._[0];

  try {
    if (cmd === 'pools') {
      const pools = await nodep0.listPools();
      console.log(JSON.stringify(pools, null, 2));
    } else if (cmd === 'stake') {
      const poolId = String(argv.poolId);
      const amountSats = Number(argv.amountSats);
      if (!Number.isFinite(amountSats) || amountSats <= 0) {
        throw new Error('amountSats must be a positive number');
      }
      const result = await svc.createAndFundStake({
        poolId,
        amountSats,
        customerRef: argv.ref ? String(argv.ref) : undefined,
      });
      console.log(JSON.stringify(result, null, 2));

      // Optional: Poll for status until active (with timeout)
      log.info('Polling stake status until active (timeout 2 minutes)...');
      const started = Date.now();
      while (Date.now() - started < 120_000) {
        const status = await nodep0.getStakeStatus(result.stakeId);
        log.info(`Current status: ${status.status}`);
        if (status.status === 'active') break;
        await sleep(3000);
      }
      const finalStatus = await nodep0.getStakeStatus(result.stakeId);
      console.log(JSON.stringify(finalStatus, null, 2));
    } else if (cmd === 'status') {
      const stakeId = String(argv.stakeId);
      const status = await nodep0.getStakeStatus(stakeId);
      console.log(JSON.stringify(status, null, 2));
    } else if (cmd === 'unstake') {
      const stakeId = String(argv.stakeId);
      const res = await nodep0.requestUnstake(stakeId);
      console.log(JSON.stringify(res, null, 2));
    } else if (cmd === 'withdraw') {
      const stakeId = String(argv.stakeId);
      const to = String(argv.to);

      // If RPC configured, we can lightly validate address format (non-fatal if not)
      if (btc.url) {
        try {
          const v = await btc.validateAddress(to);
          if (!v?.isvalid) {
            throw new Error(`Invalid BTC address: ${to}`);
          }
        } catch (e) {
          throw new Error(`Destination address validation failed: ${String(e)}`);
        }
      } else {
        log.warn('Skipping destination address validation (bitcoind RPC not configured)');
      }

      const res = await nodep0.withdraw({ stakeId, toAddress: to });
      console.log(JSON.stringify(res, null, 2));
    } else {
      throw new Error(`Unknown command: ${cmd}`);
    }
  } catch (err) {
    // Production-style error handling: sanitized logging
    const message = err instanceof Error ? err.message : String(err);
    log.error('Command failed:', message);
    process.exitCode = 1;
  }
}

main().catch((e) => {
  log.error('Fatal:', e instanceof Error ? e.message : String(e));
  process.exitCode = 1;
});

#!/usr/bin/env python3
"""
Automate web server setup using the ProofPayy API.

This script demonstrates a production-ready approach to automating a web server
provisioning workflow driven by a REST API that resembles "ProofPayy".
It implements robust error handling, retries, logging, and a clean CLI.

NOTE:
- The API endpoints used here are conventional REST-style placeholders and may differ
  from ProofPayy's actual API. Adjust the endpoints and payloads to match the official
  API documentation before using in production.
- Ensure you have a valid API key with necessary permissions.

Dependencies:
- requests

Install:
- pip install requests

Environment:
- PROOFPAYY_API_KEY: API key for authenticating requests.
- PROOFPAYY_BASE_URL: Base URL for the ProofPayy API (default: https://api.proofpayy.com/v1).

Example:
- python setup_web_server.py --domain example.com --email admin@example.com --region us-east --size s-1vcpu-1gb
"""

from __future__ import annotations

import argparse
import json
import logging
import os
import re
import sys
import time
import uuid
from dataclasses import dataclass
from typing import Any, Dict, Iterable, Optional

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry


# ----------------------------- Configuration ----------------------------- #

DEFAULT_BASE_URL = "https://api.proofpayy.com/v1"
DEFAULT_TIMEOUT_SECONDS = 30
DEFAULT_POLL_INTERVAL_SECONDS = 5
DEFAULT_POLL_TIMEOUT_SECONDS = 900  # 15 minutes


# ------------------------------- Exceptions ------------------------------ #

class ApiError(Exception):
    """Represents an API error with detailed context."""

    def __init__(
        self,
        message: str,
        status_code: Optional[int] = None,
        response_text: Optional[str] = None,
        details: Optional[Dict[str, Any]] = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.response_text = response_text
        self.details = details or {}

    def __str__(self) -> str:
        base = super().__str__()
        parts = [base]
        if self.status_code is not None:
            parts.append(f"(status={self.status_code})")
        if self.details:
            parts.append(f"details={self.details}")
        return " ".join(parts)


# ------------------------------ Data Classes ----------------------------- #

@dataclass(frozen=True)
class ServerSpec:
    name: str
    region: str
    size: str
    image: str = "ubuntu-22-04-lts"


@dataclass(frozen=True)
class SSLSpec:
    domain: str
    email: str
    challenge: str = "http-01"
    auto_redirect: bool = True


# ---------------------------- Utility Functions -------------------------- #

def validate_domain(domain: str) -> None:
    """
    Validate a domain string. Raises ValueError if invalid.
    """
    # Basic RFC-compliant domain validation (simplified)
    domain_regex = re.compile(
        r"^(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)"
        r"(?:\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\.[A-Za-z]{2,63}$"
    )
    if not domain_regex.match(domain):
        raise ValueError(f"Invalid domain name: {domain}")


def generate_nginx_config(domain: str, upstream_port: int = 3000, ssl_enabled: bool = True) -> str:
    """
    Generate a basic NGINX server block configuration.
    Adjust as needed for your stack.
    """
    server_block_http = f"""
server {{
    listen 80;
    listen [::]:80;
    server_name {domain};

    # ACME challenge location for HTTP-01 validation
    location /.well-known/acme-challenge/ {{
        root /var/www/{domain}/;
    }}

    {"return 301 https://$host$request_uri;" if ssl_enabled else f"proxy_pass http://127.0.0.1:{upstream_port};"}
}}
""".strip()

    if not ssl_enabled:
        return server_block_http

    server_block_https = f"""
server {{
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name {domain};

    ssl_certificate /etc/letsencrypt/live/{domain}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/{domain}/privkey.pem;
    ssl_trusted_certificate /etc/letsencrypt/live/{domain}/chain.pem;

    # Recommended TLS config snippets (assumes they're present on the server)
    ssl_session_timeout 1d;
    ssl_session_cache shared:SSL:50m;
    ssl_session_tickets off;

    # HSTS (optional; enable once HTTPS is confirmed working)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

    # Proxy to application
    location / {{
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_pass http://127.0.0.1:{upstream_port};
    }}
}}
""".strip()

    return f"{server_block_http}\n\n{server_block_https}\n"


def build_logger(verbosity: int) -> logging.Logger:
    """
    Create and configure a logger.
    """
    level = logging.WARNING
    if verbosity == 1:
        level = logging.INFO
    elif verbosity >= 2:
        level = logging.DEBUG

    logger = logging.getLogger("proofpayy_setup")
    logger.setLevel(level)
    handler = logging.StreamHandler(stream=sys.stdout)
    handler.setLevel(level)
    formatter = logging.Formatter(
        fmt="%(asctime)s %(levelname)s %(name)s - %(message)s",
        datefmt="%Y-%m-%dT%H:%M:%S%z",
    )
    handler.setFormatter(formatter)
    if not logger.handlers:
        logger.addHandler(handler)
    return logger


# ------------------------------- API Client ------------------------------ #

class ProofPayyClient:
    """
    Minimal ProofPayy API client with retries and timeouts.

    Adjust endpoint paths and schemas to match the official ProofPayy API.
    """

    def __init__(
        self,
        api_key: str,
        base_url: str = DEFAULT_BASE_URL,
        timeout: int = DEFAULT_TIMEOUT_SECONDS,
        user_agent: str = "ProofPayySetup/1.0",
        logger: Optional[logging.Logger] = None,
    ) -> None:
        if not api_key:
            raise ValueError("API key is required")

        self.api_key = api_key
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.logger = logger or logging.getLogger("proofpayy_setup")

        self.session = requests.Session()
        self.session.headers.update(
            {
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
                "User-Agent": user_agent,
            }
        )

        # Configure retries for transient errors.
        retry = Retry(
            total=5,
            backoff_factor=0.5,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=frozenset({"GET", "POST", "PUT", "PATCH", "DELETE"}),
            raise_on_status=False,
        )
        adapter = HTTPAdapter(max_retries=retry, pool_connections=10, pool_maxsize=20)
        self.session.mount("https://", adapter)
        self.session.mount("http://", adapter)

    def _request(
        self,
        method: str,
        path: str,
        *,
        json_body: Optional[Dict[str, Any]] = None,
        params: Optional[Dict[str, Any]] = None,
        idempotency_key: Optional[str] = None,
        timeout: Optional[int] = None,
    ) -> Dict[str, Any]:
        """
        Internal HTTP request helper with error handling.
        """
        url = f"{self.base_url}{path}"
        headers = {}
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key

        self.logger.debug("Request: %s %s json=%s params=%s", method, url, json_body, params)

        try:
            resp = self.session.request(
                method,
                url,
                json=json_body,
                params=params,
                headers=headers,
                timeout=timeout or self.timeout,
            )
        except requests.RequestException as e:
            raise ApiError(f"Network error calling {method} {url}", details={"error": str(e)})

        content_type = resp.headers.get("Content-Type", "")
        text = resp.text or ""

        if not resp.ok:
            # Attempt to parse structured error
            err_details: Dict[str, Any] = {}
            if "application/json" in content_type:
                try:
                    err_details = resp.json()
                except Exception:
                    err_details = {"raw": text[:1000]}
            else:
                err_details = {"raw": text[:1000]}
            raise ApiError(
                f"API error for {method} {url}",
                status_code=resp.status_code,
                response_text=text[:1000],
                details=err_details,
            )

        if "application/json" in content_type:
            try:
                data = resp.json()
            except json.JSONDecodeError:
                raise ApiError(f"Invalid JSON response from {url}", response_text=text[:500])
            self.logger.debug("Response: %s", data)
            return data
        else:
            # Fallback to text content
            self.logger.debug("Response (text): %s", text[:500])
            return {"raw": text}

    # ---------------------- Hypothetical API Operations --------------------- #

    def create_server(self, spec: ServerSpec) -> Dict[str, Any]:
        """
        Create a new server. Returns server object including id and initial status.
        Adjust path and payload to API spec.
        """
        payload = {
            "name": spec.name,
            "region": spec.region,
            "size": spec.size,
            "image": spec.image,
        }
        return self._request(
            "POST",
            "/servers",
            json_body=payload,
            idempotency_key=str(uuid.uuid4()),
        )

    def get_server(self, server_id: str) -> Dict[str, Any]:
        """
        Retrieve server by ID.
        """
        return self._request("GET", f"/servers/{server_id}")

    def wait_for_server_active(
        self,
        server_id: str,
        *,
        timeout_seconds: int = DEFAULT_POLL_TIMEOUT_SECONDS,
        poll_interval_seconds: int = DEFAULT_POLL_INTERVAL_SECONDS,
    ) -> Dict[str, Any]:
        """
        Poll the server until status indicates it's active/ready or timeout occurs.
        """
        deadline = time.time() + timeout_seconds
        last_status = None

        while time.time() < deadline:
            server = self.get_server(server_id)
            status = server.get("status")
            if status != last_status:
                self.logger.info("Server %s status: %s", server_id, status)
                last_status = status
            if status in ("active", "running", "ready"):
                return server
            time.sleep(poll_interval_seconds)

        raise TimeoutError(f"Timed out waiting for server {server_id} to become active")

    def open_firewall(self, server_id: str, ports: Iterable[int]) -> Dict[str, Any]:
        """
        Open firewall ports for the server.
        """
        payload = {"ports": [{"protocol": "tcp", "port": p} for p in ports]}
        return self._request("POST", f"/servers/{server_id}/firewall/open", json_body=payload)

    def attach_domain(self, server_id: str, domain: str) -> Dict[str, Any]:
        """
        Attach a domain to the server (may create DNS records in provider if API supports it).
        """
        payload = {"domain": domain}
        return self._request("POST", f"/servers/{server_id}/domains", json_body=payload)

    def request_ssl(self, ssl: SSLSpec) -> Dict[str, Any]:
        """
        Request an SSL certificate using ACME. The API should handle challenges and issuance.
        """
        payload = {
            "domain": ssl.domain,
            "email": ssl.email,
            "challenge": ssl.challenge,
            "auto_redirect": ssl.auto_redirect,
        }
        return self._request(
            "POST",
            "/ssl/certificates",
            json_body=payload,
            idempotency_key=str(uuid.uuid4()),
        )

    def get_ssl(self, certificate_id: str) -> Dict[str, Any]:
        """
        Get SSL certificate status/details.
        """
        return self._request("GET", f"/ssl/certificates/{certificate_id}")

    def deploy_nginx_config(
        self,
        server_id: str,
        domain: str,
        config_text: str,
        reload: bool = True,
    ) -> Dict[str, Any]:
        """
        Deploy an NGINX config file to the server and optionally reload NGINX.
        """
        payload = {
            "path": f"/etc/nginx/sites-available/{domain}.conf",
            "content": config_text,
            "symlink": {
                "from": f"/etc/nginx/sites-available/{domain}.conf",
                "to": f"/etc/nginx/sites-enabled/{domain}.conf",
            },
            "reload_service": "nginx" if reload else None,
            "create_dirs": True,
        }
        return self._request("POST", f"/servers/{server_id}/files/deploy", json_body=payload)

    def wait_for_ssl_issued(
        self,
        certificate_id: str,
        *,
        timeout_seconds: int = 600,
        poll_interval_seconds: int = 5,
    ) -> Dict[str, Any]:
        """
        Wait for SSL certificate issuance.
        """
        deadline = time.time() + timeout_seconds
        last_status = None

        while time.time() < deadline:
            cert = self.get_ssl(certificate_id)
            status = cert.get("status")
            if status != last_status:
                self.logger.info("Certificate %s status: %s", certificate_id, status)
                last_status = status
            if status in ("issued", "active", "ready"):
                return cert
            if status in ("failed", "error"):
                raise ApiError(f"SSL issuance failed for id={certificate_id}", details=cert)
            time.sleep(poll_interval_seconds)

        raise TimeoutError(f"Timed out waiting for SSL certificate {certificate_id} to be issued")

    def create_directory(self, server_id: str, path: str, owner: str = "root", mode: str = "0755") -> Dict[str, Any]:
        """
        Create a directory on the remote server.
        """
        payload = {"path": path, "owner": owner, "mode": mode}
        return self._request("POST", f"/servers/{server_id}/files/mkdir", json_body=payload)

    def write_file(self, server_id: str, path: str, content: str, owner: str = "root", mode: str = "0644") -> Dict[str, Any]:
        """
        Write a file to the remote server.
        """
        payload = {"path": path, "content": content, "owner": owner, "mode": mode}
        return self._request("POST", f"/servers/{server_id}/files/write", json_body=payload)

    def run_command(self, server_id: str, command: str, timeout_seconds: int = 120) -> Dict[str, Any]:
        """
        Run a shell command on the remote server.
        """
        payload = {"command": command, "timeout": timeout_seconds}
        return self._request("POST", f"/servers/{server_id}/commands/run", json_body=payload)

    def ensure_nginx_installed(self, server_id: str) -> None:
        """
        Ensure nginx is installed and enabled. Adjust commands for OS/distro if needed.
        """
        # Update package lists and install nginx if missing. Using non-interactive flags.
        commands = [
            "which nginx || (sudo apt-get update -y && sudo apt-get install -y nginx)",
            "sudo systemctl enable nginx",
            "sudo systemctl start nginx",
            "sudo nginx -t",
        ]
        for cmd in commands:
            self.run_command(server_id, cmd)

    def get_server_public_ip(self, server: Dict[str, Any]) -> Optional[str]:
        """
        Extract public IPv4 address from server object (adjust to API schema).
        """
        # Example schema options:
        # - server["network"]["public_ipv4"]
        # - server["ip_address"]
        # - server["addresses"]["public"][0]["ip"]
        for key in ("ip_address", "public_ip", "public_ipv4"):
            if ip := server.get(key):
                return ip

        net = server.get("network") or {}
        if isinstance(net, dict):
            if ip := net.get("public_ipv4"):
                return ip

        addresses = server.get("addresses")
        if isinstance(addresses, dict):
            public = addresses.get("public")
            if isinstance(public, list) and public:
                ip = public[0].get("ip")
                if ip:
                    return ip

        return None


# --------------------------------- CLI ----------------------------------- #

def parse_args() -> argparse.Namespace:
    """
    Parse CLI arguments.
    """
    parser = argparse.ArgumentParser(
        description="Automate web server setup using ProofPayy API."
    )
    parser.add_argument("--domain", required=True, help="Domain name to configure (e.g., example.com)")
    parser.add_argument("--email", required=True, help="Email for SSL certificate registration and notifications")
    parser.add_argument("--region", required=True, help="Server region/zone (e.g., us-east)")
    parser.add_argument("--size", required=True, help="Server size/flavor (e.g., s-1vcpu-1gb)")
    parser.add_argument("--image", default="ubuntu-22-04-lts", help="OS image identifier")
    parser.add_argument("--upstream-port", type=int, default=3000, help="App upstream port behind NGINX")
    parser.add_argument("--no-https", action="store_true", help="Disable HTTPS setup and SSL issuance")
    parser.add_argument("--timeout", type=int, default=DEFAULT_POLL_TIMEOUT_SECONDS, help="Overall provisioning wait timeout in seconds")
    parser.add_argument("--poll-interval", type=int, default=DEFAULT_POLL_INTERVAL_SECONDS, help="Polling interval in seconds")
    parser.add_argument("--verbose", "-v", action="count", default=0, help="Increase verbosity (-v, -vv)")
    parser.add_argument("--dry-run", action="store_true", help="Only validate and print planned actions")
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    logger = build_logger(args.verbose)

    # Validate domain
    try:
        validate_domain(args.domain)
    except ValueError as ve:
        logger.error("Domain validation failed: %s", ve)
        sys.exit(2)

    # Environment variables for credentials and base URL
    api_key = os.environ.get("PROOFPAYY_API_KEY", "").strip()
    base_url = os.environ.get("PROOFPAYY_BASE_URL", DEFAULT_BASE_URL).strip() or DEFAULT_BASE_URL

    if not api_key:
        logger.error("Missing PROOFPAYY_API_KEY environment variable.")
        sys.exit(2)

    client = ProofPayyClient(
        api_key=api_key,
        base_url=base_url,
        timeout=DEFAULT_TIMEOUT_SECONDS,
        logger=logger,
    )

    spec = ServerSpec(
        name=args.domain.replace(".", "-"),
        region=args.region,
        size=args.size,
        image=args.image,
    )
    ssl_spec = SSLSpec(
        domain=args.domain,
        email=args.email,
        challenge="http-01",
        auto_redirect=not args.no_https,
    )

    # Plan summary for dry-run
    if args.dry_run:
        print(json.dumps(
            {
                "action": "plan",
                "server_spec": spec.__dict__,
                "ssl_spec": ssl_spec.__dict__,
                "upstream_port": args.upstream_port,
                "https_enabled": not args.no_https,
                "base_url": base_url,
            },
            indent=2,
        ))
        return

    try:
        # 1) Create server
        logger.info("Creating server in region=%s size=%s image=%s", spec.region, spec.size, spec.image)
        server = client.create_server(spec)
        server_id = server.get("id")
        if not server_id:
            raise ApiError("Server creation response missing 'id'", details=server)

        # 2) Wait for server to become active
        logger.info("Waiting for server to become active...")
        server = client.wait_for_server_active(
            server_id,
            timeout_seconds=args.timeout,
            poll_interval_seconds=args.poll_interval,
        )

        # Extract IP for display
        public_ip = client.get_server_public_ip(server) or "UNKNOWN"
        logger.info("Server is active. Public IP: %s", public_ip)

        # 3) Open firewall for HTTP/HTTPS
        logger.info("Opening firewall ports 80 and 443")
        client.open_firewall(server_id, ports=[80, 443])

        # 4) Ensure NGINX installed and configured
        logger.info("Ensuring NGINX is installed")
        client.ensure_nginx_installed(server_id)

        # 5) Attach domain to server (and/or ensure DNS records are created)
        logger.info("Attaching domain %s to server %s", args.domain, server_id)
        client.attach_domain(server_id, args.domain)

        # 6) Prepare web root for ACME challenges and site content
        web_root = f"/var/www/{args.domain}"
        logger.info("Creating web root at %s", web_root)
        client.create_directory(server_id, web_root, owner="www-data", mode="0755")
        client.create_directory(server_id, f"{web_root}/.well-known/acme-challenge", owner="www-data", mode="0755")

        # 7) Generate and deploy NGINX config
        nginx_conf = generate_nginx_config(
            domain=args.domain,
            upstream_port=args.upstream_port,
            ssl_enabled=not args.no_https,
        )
        logger.info("Deploying NGINX configuration")
        client.deploy_nginx_config(server_id, args.domain, config_text=nginx_conf, reload=True)

        # 8) Request and wait for SSL certificate (if enabled)
        certificate_info: Optional[Dict[str, Any]] = None
        if not args.no_https:
            logger.info("Requesting SSL certificate for %s", args.domain)
            cert_resp = client.request_ssl(ssl_spec)
            certificate_id = cert_resp.get("id")
            if not certificate_id:
                raise ApiError("SSL request response missing 'id'", details=cert_resp)

            logger.info("Waiting for SSL certificate issuance...")
            certificate_info = client.wait_for_ssl_issued(
                certificate_id,
                timeout_seconds=min(args.timeout, 600),
                poll_interval_seconds=args.poll_interval,
            )

            # Reload NGINX after cert issuance to apply TLS
            logger.info("Reloading NGINX to apply SSL certificate")
            client.run_command(server_id, "sudo nginx -t && sudo systemctl reload nginx")

        # 9) Final summary output
        summary = {
            "server_id": server_id,
            "public_ip": public_ip,
            "domain": args.domain,
            "https_enabled": not args.no_https,
            "certificate": {
                "id": certificate_info.get("id") if certificate_info else None,
                "status": certificate_info.get("status") if certificate_info else None,
            }
            if certificate_info
            else None,
            "upstream_port": args.upstream_port,
            "nginx_site": f"/etc/nginx/sites-available/{args.domain}.conf",
        }

        print(json.dumps(summary, indent=2))

    except TimeoutError as te:
        logger.error("Timeout: %s", te)
        sys.exit(3)
    except ApiError as ae:
        # Avoid printing sensitive values; details should be API responses only.
        logger.error("API error: %s", ae)
        sys.exit(4)
    except KeyboardInterrupt:
        logger.error("Interrupted by user")
        sys.exit(130)
    except Exception as e:
        logger.exception("Unexpected error: %s", e)
        sys.exit(1)


if __name__ == "__main__":
    main()

/**
 * Savaz Pregnancy Profile Order Submission
 * ----------------------------------------
 * Production-ready JavaScript helper to submit a medical order for a
 * Pregnancy Profile (Perfil de Embarazo) to Laboratorio Savaz's online system.
 *
 * Notes:
 * - Configure the endpoint and API key via parameters or environment variables.
 * - Implements robust validation, retries with exponential backoff, and timeouts.
 * - Uses an idempotency key to prevent duplicate orders on retries.
 *
 * Environment variables supported:
 * - SAVAZ_BASE_URL (e.g., https://api.savaz.lab/v1)
 * - SAVAZ_API_KEY  (Bearer token)
 */

/* eslint-disable no-console */

/**
 * Attempt to use global fetch (Node 18+/browsers). Fallback to node-fetch if needed.
 * This keeps the helper runnable in varied environments.
 */
const fetchFn =
  typeof fetch === "function"
    ? fetch.bind(globalThis)
    : async (...args) => {
        const mod = await import("node-fetch");
        return mod.default(...args);
      };

const { createHash, randomUUID } = await (async () => {
  try {
    // Node >= 15 supports node:crypto
    return await import("node:crypto");
  } catch {
    // Fallback for older bundlers; this may throw if crypto is unavailable
    return await import("crypto");
  }
})();

/**
 * Constant that represents the Pregnancy Profile panel.
 * Adjust codes to match Savaz's official test directory.
 */
const PREGNANCY_PROFILE_PANEL = Object.freeze({
  code: "PERFIL_EMBARAZO",
  name: "Perfil de Embarazo",
  // Optional: list of typical tests in this panel (for internal reference/logging)
  tests: [
    { code: "CBC", name: "Biometría Hemática Completa" },
    { code: "UA", name: "EGO / Examen General de Orina" },
    { code: "GLU-FAST", name: "Glucosa en Ayuno" },
    { code: "HIV-AgAb", name: "HIV 1/2 Ag/Ab" },
    { code: "HBsAg", name: "Antígeno de Superficie Hepatitis B" },
    { code: "HCV-Ab", name: "Anticuerpos Hepatitis C" },
    { code: "RPR", name: "VDRL/RPR Sífilis" },
    { code: "RUB-IgG", name: "Rubéola IgG" },
    { code: "TOXO-IgG", name: "Toxoplasma IgG" },
    { code: "TOXO-IgM", name: "Toxoplasma IgM" },
    { code: "ABO-RH", name: "Grupo Sanguíneo y RH" }
  ]
});

/**
 * Custom error for Savaz API failures.
 */
class SavazApiError extends Error {
  /**
   * @param {string} message - Human-readable message
   * @param {object} opts
   * @param {number} [opts.status] - HTTP status code
   * @param {string} [opts.code] - API-specific error code
   * @param {any} [opts.details] - Additional details or response body
   * @param {string} [opts.requestId] - Server-side request ID (if provided)
   */
  constructor(message, { status, code, details, requestId } = {}) {
    super(message);
    this.name = "SavazApiError";
    this.status = status;
    this.code = code;
    this.details = details;
    this.requestId = requestId;
  }
}

/**
 * Sleep helper for retry backoff.
 * @param {number} ms
 * @returns {Promise<void>}
 */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Compute a stable idempotency key to avoid duplicate orders on retries.
 * Combines selected payload fields and hashes them.
 * @param {object} payload
 * @returns {string}
 */
function computeIdempotencyKey(payload) {
  const stable = JSON.stringify(
    {
      version: 1,
      patient: {
        firstName: payload?.patient?.firstName,
        lastName: payload?.patient?.lastName,
        maternalLastName: payload?.patient?.maternalLastName,
        nationalId: payload?.patient?.nationalId,
        mrn: payload?.patient?.mrn,
        dob: payload?.patient?.dateOfBirth
      },
      panelCode: payload?.order?.panelCode,
      collectionDateTime: payload?.order?.collection?.dateTime
    },
    Object.keys
  );
  return createHash("sha256").update(stable).digest("hex");
}

/**
 * Basic PII redaction for logs/errors.
 * @param {any} obj
 * @returns {any}
 */
function redactPII(obj) {
  if (!obj || typeof obj !== "object") return obj;
  const copy = JSON.parse(JSON.stringify(obj));
  const redactFields = new Set([
    "firstName",
    "lastName",
    "maternalLastName",
    "email",
    "phone",
    "nationalId",
    "mrn",
    "addressLine1",
    "addressLine2",
    "postalCode",
    "memberId",
    "groupNumber"
  ]);

  function walk(o) {
    if (!o || typeof o !== "object") return;
    for (const k of Object.keys(o)) {
      const v = o[k];
      if (redactFields.has(k)) {
        o[k] = v ? "***REDACTED***" : v;
      } else if (typeof v === "object") {
        walk(v);
      }
    }
  }
  walk(copy);
  return copy;
}

/**
 * Determine if an HTTP status is transient (eligible for retry).
 * @param {number} status
 */
function isTransientStatus(status) {
  return status === 408 || status === 409 || status === 425 || status === 429 || (status >= 500 && status < 600);
}

/**
 * Perform a fetch with timeout, retries, and backoff for transient failures.
 * @param {string} url
 * @param {RequestInit & { timeoutMs?: number, expectedStatuses?: number[] }} options
 * @param {number} retries
 * @param {number} backoffBaseMs
 * @returns {Promise<Response>}
 */
async function fetchWithRetry(url, options, retries = 3, backoffBaseMs = 300) {
  const { timeoutMs = 10000, ...rest } = options || {};
  let attempt = 0;

  while (true) {
    attempt += 1;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const res = await fetchFn(url, { ...rest, signal: controller.signal });

      if (!res.ok && isTransientStatus(res.status) && attempt <= retries) {
        const jitter = Math.floor(Math.random() * 100);
        const delay = backoffBaseMs * 2 ** (attempt - 1) + jitter;
        await sleep(delay);
        continue;
      }

      clearTimeout(timer);
      return res;
    } catch (err) {
      clearTimeout(timer);

      // Retry on network/timeout errors
      const isAbort = err && typeof err === "object" && err.name === "AbortError";
      const isNetwork =
        err && typeof err === "object" && (err.code === "ECONNRESET" || err.code === "ETIMEDOUT" || err.code === "EAI_AGAIN");

      if ((isAbort || isNetwork) && attempt <= retries) {
        const jitter = Math.floor(Math.random() * 100);
        const delay = backoffBaseMs * 2 ** (attempt - 1) + jitter;
        await sleep(delay);
        continue;
      }
      throw err;
    }
  }
}

/**
 * Very basic ISO date validation.
 * @param {string} iso
 */
function isValidISODate(iso) {
  if (typeof iso !== "string") return false;
  const d = new Date(iso);
  return !Number.isNaN(d.getTime());
}

/**
 * Validates pregnancy-specific constraints and required fields.
 * Throws errors describing the exact issue.
 * @param {object} input
 */
function validateInput(input) {
  if (!input || typeof input !== "object") throw new Error("Input is required.");

  const { patient, orderingPhysician, collection, billing } = input;

  // Patient validations
  if (!patient || typeof patient !== "object") throw new Error("patient is required.");
  const requiredPatient = ["firstName", "lastName", "dateOfBirth", "sex"];
  for (const f of requiredPatient) {
    if (!patient[f]) throw new Error(`patient.${f} is required.`);
  }
  if (patient.sex !== "F") {
    throw new Error("patient.sex must be 'F' for pregnancy profile orders.");
  }
  if (!isValidISODate(patient.dateOfBirth)) {
    throw new Error("patient.dateOfBirth must be a valid ISO date string.");
  }
  if (patient.lmpDate && !isValidISODate(patient.lmpDate)) {
    throw new Error("patient.lmpDate must be a valid ISO date string when provided.");
  }
  if (patient.pregnancyWeeks != null) {
    const w = Number(patient.pregnancyWeeks);
    if (!Number.isFinite(w) || w < 0 || w > 45) {
      throw new Error("patient.pregnancyWeeks must be a number between 0 and 45.");
    }
  }

  // Ordering physician
  if (!orderingPhysician || typeof orderingPhysician !== "object") {
    throw new Error("orderingPhysician is required.");
  }
  const requiredPhysician = ["fullName", "license"];
  for (const f of requiredPhysician) {
    if (!orderingPhysician[f]) throw new Error(`orderingPhysician.${f} is required.`);
  }

  // Collection details
  if (!collection || typeof collection !== "object") throw new Error("collection is required.");
  if (!collection.dateTime || !isValidISODate(collection.dateTime)) {
    throw new Error("collection.dateTime must be a valid ISO date string.");
  }
  if (!collection.locationType || !["patient-home", "clinic", "lab"].includes(collection.locationType)) {
    throw new Error("collection.locationType must be one of: 'patient-home' | 'clinic' | 'lab'.");
  }

  // Billing
  if (!billing || typeof billing !== "object") throw new Error("billing is required.");
  if (!["self-pay", "insurance"].includes(billing.type)) {
    throw new Error("billing.type must be 'self-pay' or 'insurance'.");
  }
  if (billing.type === "insurance") {
    if (!billing.insurance || !billing.insurance.provider || !billing.insurance.memberId) {
      throw new Error("billing.insurance.provider and billing.insurance.memberId are required for insurance billing.");
    }
  }
}

/**
 * Build the Savaz API-compliant payload from the input.
 * @param {object} input
 * @returns {object}
 */
function buildSavazPayload(input) {
  const {
    patient,
    orderingPhysician,
    collection,
    billing,
    diagnosisCodes = ["Z34.9"], // Encounter for supervision of normal pregnancy, unspecified
    priority = "routine",
    fastingRequired = false,
    notes
  } = input;

  const payload = {
    patient: {
      identifiers: {
        nationalId: patient.nationalId || null,
        mrn: patient.mrn || null
      },
      firstName: patient.firstName,
      lastName: patient.lastName,
      maternalLastName: patient.maternalLastName || null,
      dateOfBirth: patient.dateOfBirth,
      sex: patient.sex,
      contact: {
        phone: patient.phone || null,
        email: patient.email || null
      },
      address: patient.address
        ? {
            addressLine1: patient.address.addressLine1 || null,
            addressLine2: patient.address.addressLine2 || null,
            city: patient.address.city || null,
            state: patient.address.state || null,
            postalCode: patient.address.postalCode || null,
            country: patient.address.country || "MX"
          }
        : null,
      obstetrics: {
        pregnancyWeeks: patient.pregnancyWeeks ?? null,
        lmpDate: patient.lmpDate || null
      }
    },
    order: {
      panelCode: PREGNANCY_PROFILE_PANEL.code,
      panelName: PREGNANCY_PROFILE_PANEL.name,
      priority,
      fastingRequired,
      diagnosisCodes,
      notes: notes || null,
      collection: {
        dateTime: collection.dateTime,
        locationType: collection.locationType, // 'patient-home' | 'clinic' | 'lab'
        locationDetails: collection.locationDetails || null
      },
      // Optional: include explicit tests if Savaz requires itemized ordering
      // tests: PREGNANCY_PROFILE_PANEL.tests.map(t => t.code)
    },
    orderingPhysician: {
      fullName: orderingPhysician.fullName,
      license: orderingPhysician.license,
      npi: orderingPhysician.npi || null,
      contact: {
        phone: orderingPhysician.phone || null,
        email: orderingPhysician.email || null
      }
    },
    billing: {
      type: billing.type,
      insurance:
        billing.type === "insurance"
          ? {
              provider: billing.insurance.provider,
              memberId: billing.insurance.memberId,
              groupNumber: billing.insurance.groupNumber || null,
              holderName: billing.insurance.holderName || null
            }
          : null
    },
    metadata: {
      source: "app",
      createdAt: new Date().toISOString()
    },
    consent: {
      hipaaAuthorization: input.consent?.hipaaAuthorization ?? true
    }
  };

  return payload;
}

/**
 * Submit a Pregnancy Profile (Perfil de Embarazo) order to Laboratorio Savaz.
 *
 * @param {object} input - Order details
 * @param {object} [config] - Configuration options
 * @param {string} [config.baseUrl=process.env.SAVAZ_BASE_URL] - Savaz API base URL
 * @param {string} [config.apiKey=process.env.SAVAZ_API_KEY] - Savaz API key (Bearer)
 * @param {number} [config.timeoutMs=10000] - Request timeout in ms
 * @param {number} [config.retries=3] - Number of retry attempts for transient errors
 * @param {string} [config.idempotencyKey] - Custom idempotency key (otherwise derived)
 * @returns {Promise<{ orderId: string, status: string, eta?: string, raw: any }>}
 *
 * Usage example:
 * (async () => {
 *   const result = await submitSavazPregnancyProfileOrder({
 *     patient: {
 *       firstName: "Ana",
 *       lastName: "García",
 *       maternalLastName: "López",
 *       nationalId: "MXC-12345678",
 *       dateOfBirth: "1992-05-10",
 *       sex: "F",
 *       phone: "+52-55-1234-5678",
 *       email: "ana.garcia@example.com",
 *       address: {
 *         addressLine1: "Av. Reforma 123",
 *         city: "CDMX",
 *         state: "CDMX",
 *         postalCode: "06000",
 *         country: "MX"
 *       },
 *       pregnancyWeeks: 12,
 *       lmpDate: "2025-06-01"
 *     },
 *     orderingPhysician: {
 *       fullName: "Dr. Juan Pérez",
 *       license: "MED-987654",
 *       phone: "+52-55-2222-3333",
 *       email: "dr.perez@clinic.mx"
 *     },
 *     collection: {
 *       dateTime: new Date(Date.now() + 3600_000).toISOString(),
 *       locationType: "clinic",
 *       locationDetails: "Clínica Central, Consultorio 3"
 *     },
 *     billing: {
 *       type: "self-pay"
 *     },
 *     notes: "Paciente en primer trimestre. Confirmar RH.",
 *     priority: "routine",
 *     fastingRequired: false
 *   }, {
 *     baseUrl: "https://sandbox.api.savaz.example/v1",
 *     apiKey: "your_api_key_here"
 *   });
 *
 *   console.log("Order submitted:", result);
 * })();
 */
async function submitSavazPregnancyProfileOrder(input, config = {}) {
  // Validate input structure and pregnancy-related constraints
  validateInput(input);

  // Resolve configuration
  const baseUrl = String(config.baseUrl || process.env.SAVAZ_BASE_URL || "").trim();
  const apiKey = String(config.apiKey || process.env.SAVAZ_API_KEY || "").trim();
  const timeoutMs = Number.isFinite(config.timeoutMs) ? Number(config.timeoutMs) : 10000;
  const retries = Number.isFinite(config.retries) ? Number(config.retries) : 3;

  if (!baseUrl) {
    throw new Error("Missing baseUrl. Provide config.baseUrl or set SAVAZ_BASE_URL.");
  }
  if (!apiKey) {
    throw new Error("Missing apiKey. Provide config.apiKey or set SAVAZ_API_KEY.");
  }

  const endpoint = baseUrl.replace(/\/+$/, "") + "/orders";
  const body = buildSavazPayload(input);
  const derivedIdemKey = computeIdempotencyKey(body);
  const idempotencyKey = config.idempotencyKey || derivedIdemKey || randomUUID();

  // Perform request with robust error handling
  let res;
  try {
    res = await fetchWithRetry(
      endpoint,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
          "Idempotency-Key": idempotencyKey
        },
        body: JSON.stringify(body),
        timeoutMs
      },
      retries,
      300
    );
  } catch (err) {
    const safeBody = redactPII(body);
    // Wrap low-level errors into SavazApiError
    throw new SavazApiError(`Network/Timeout error contacting Savaz: ${err?.message || String(err)}`, {
      details: { request: { url: endpoint, body: safeBody } }
    });
  }

  let responseBody = null;
  const requestId = res.headers.get("x-request-id") || res.headers.get("x-correlation-id") || null;

  // Attempt to parse JSON safely
  try {
    const text = await res.text();
    responseBody = text ? JSON.parse(text) : null;
  } catch {
    // leave responseBody as text or null if not JSON
  }

  if (!res.ok) {
    // Prepare safe error details
    const safeRequest = redactPII(body);
    const safeResponse = redactPII(responseBody);
    const message =
      responseBody?.message ||
      responseBody?.error ||
      `Savaz API error (status ${res.status}) while creating order`;
    throw new SavazApiError(message, {
      status: res.status,
      code: responseBody?.code,
      details: { request: safeRequest, response: safeResponse },
      requestId
    });
  }

  // Map/normalize response
  const orderId = responseBody?.orderId || responseBody?.id || null;
  const status = responseBody?.status || "submitted";
