 * @param {string|undefined} apiKey
 */
function buildHeaders(apiKey) {
  /** @type {Record<string, string>} */
  const headers = {
    'Accept': 'application/json',
  };
  // Add Authorization header if apiKey present
  if (apiKey && typeof apiKey === 'string') {
