#!/usr/bin/env python3
"""
Retrieve and display information about softwood lumber (including its uses in construction and furniture)
as described on Atilumber's website.

This script:
- Respects robots.txt
- Attempts to discover relevant pages via sitemap and limited crawling
- Extracts and prints sentences mentioning softwood lumber and its uses
- Includes robust error handling, logging, and timeouts

Dependencies:
    pip install requests beautifulsoup4 lxml

Usage:
    python softwood_info_scraper.py
    python softwood_info_scraper.py --domain https://www.atilumber.com --max-pages 30 --delay 1.5

Notes:
- Use responsibly. Always respect the site's robots.txt and terms of service.
- Output reflects live website content at execution time.
"""

from __future__ import annotations

import argparse
import logging
import random
import re
import sys
import time
from dataclasses import dataclass, field
from typing import Iterable, List, Optional, Set, Tuple
from urllib.parse import urljoin, urlparse, urlunparse
from urllib.robotparser import RobotFileParser

import requests
from bs4 import BeautifulSoup, SoupStrainer


@dataclass
class ScraperConfig:
    # Candidate base domains to try (the first accessible one will be used)
    base_domains: List[str] = field(default_factory=lambda: [
        "https://www.atilumber.com",
        "https://atilumber.com"
    ])
    user_agent: str = "Mozilla/5.0 (compatible; SoftwoodInfoBot/1.0; +https://example.com/bot-info)"
    timeout: int = 12
    delay: float = 1.0  # polite delay between requests (seconds)
    max_pages: int = 20  # max pages to fetch for candidate discovery and extraction
    connect_retries: int = 2
    verify_tls: bool = True

    # Keyword logic: we want sentences that include softwood + uses in construction/furniture
    core_keywords: List[str] = field(default_factory=lambda: ["softwood", "soft wood"])
    construction_keywords: List[str] = field(default_factory=lambda: [
        "construction", "building", "framing", "structural", "decking", "sheathing", "stud", "joist"
    ])
    furniture_keywords: List[str] = field(default_factory=lambda: [
        "furniture", "cabinet", "cabinetry", "millwork", "joinery", "interior", "paneling"
    ])

    # URL discovery helpers
    url_includes: List[str] = field(default_factory=lambda: [
        "softwood", "soft-wood", "lumber", "wood", "products"
    ])
    url_excludes: List[str] = field(default_factory=lambda: [
        "pdf", "login", "cart", "checkout", "search", "privacy", "terms"
    ])


class SoftwoodInfoScraper:
    def __init__(self, config: ScraperConfig, logger: Optional[logging.Logger] = None) -> None:
        self.config = config
        self.logger = logger or logging.getLogger(__name__)
        self.session = requests.Session()
        self.session.headers.update({"User-Agent": self.config.user_agent})
        self.rp: Optional[RobotFileParser] = None
        self.base_domain: Optional[str] = None

    def run(self) -> int:
        """Main execution method. Returns exit code (0 success, non-zero otherwise)."""
        try:
            self.base_domain = self._select_accessible_domain(self.config.base_domains)
            if not self.base_domain:
                self.logger.error("No accessible Atilumber domain found.")
                return 2

            self.logger.info("Using base domain: %s", self.base_domain)
            if not self._init_robots(self.base_domain):
                self.logger.warning("robots.txt could not be loaded; proceeding cautiously.")

            candidate_urls = self._discover_candidate_urls(self.base_domain)
            if not candidate_urls:
                self.logger.error("No candidate pages discovered for softwood/lumber.")
                return 3

            self.logger.info("Discovered %d candidate URL(s).", len(candidate_urls))

            extracted = self._extract_relevant_sentences(candidate_urls)
            if not extracted:
                self.logger.warning("No relevant sentences found on discovered pages.")
                return 4

            self._print_results(extracted)
            return 0

        except KeyboardInterrupt:
            self.logger.warning("Interrupted by user.")
            return 130
        except Exception as exc:
            self.logger.exception("Unexpected error: %s", exc)
            return 1

    def _select_accessible_domain(self, domains: Iterable[str]) -> Optional[str]:
        """Return the first domain that responds to a HEAD/GET request."""
        for d in domains:
            url = self._normalize_url(d)
            try:
                if self._allowed(url) and self._head_ok(url):
                    return url
            except Exception as e:
                self.logger.debug("Domain check failed for %s: %s", url, e)
        return None

    def _init_robots(self, base: str) -> bool:
        """Initialize robots.txt parser for the base domain."""
        try:
            parsed = urlparse(base)
            robots_url = urlunparse((parsed.scheme, parsed.netloc, "/robots.txt", "", "", ""))
            rp = RobotFileParser()
            rp.set_url(robots_url)
            rp.read()
            self.rp = rp
            # If robots returns no entries, RobotFileParser.can_fetch returns True by default
            return True
        except Exception as e:
            self.logger.debug("Failed to load robots.txt: %s", e)
            self.rp = None
            return False

    def _allowed(self, url: str) -> bool:
        """Check robots.txt allowance for a given URL."""
        if not self.rp:
            return True
        try:
            return self.rp.can_fetch(self.config.user_agent, url)
        except Exception:
            return True

    def _head_ok(self, url: str) -> bool:
        """Test domain availability quickly with HEAD, fallback to GET."""
        try:
            resp = self.session.head(url, timeout=self.config.timeout, allow_redirects=True, verify=self.config.verify_tls)
            if 200 <= resp.status_code < 400:
                return True
        except requests.RequestException:
            pass
        # Fallback to GET
        try:
            resp = self.session.get(url, timeout=self.config.timeout, allow_redirects=True, verify=self.config.verify_tls)
            return 200 <= resp.status_code < 400
        except requests.RequestException:
            return False

    def _discover_candidate_urls(self, base: str) -> Set[str]:
        """Discover candidate URLs using sitemap, then fallback to lightweight crawl."""
        urls: Set[str] = set()

        # 1) Try sitemap discovery
        sitemap_urls = [
            urljoin(base, "/sitemap.xml"),
            urljoin(base, "/sitemap_index.xml"),
            urljoin(base, "/sitemap_index.xml.gz"),
        ]
        for sm in sitemap_urls:
            urls |= self._parse_sitemap_for_candidates(sm)

        if urls:
            return urls

        # 2) Fallback: crawl homepage and first-level links
        frontier: List[str] = [base]
        visited: Set[str] = set()
        while frontier and len(visited) < self.config.max_pages:
            current = frontier.pop(0)
            if current in visited:
                continue
            visited.add(current)

            if not self._allowed(current):
                self.logger.debug("Skipping disallowed URL by robots: %s", current)
                continue

            html = self._safe_get(current)
            if not html:
                continue

            links = self._extract_links(current, html)
            # Add links that look promising
            for link in links:
                if self._is_candidate_url(link):
                    urls.add(link)
                # Expand frontier conservatively (same host, non-static)
                if self._same_host(base, link) and self._is_crawlable(link):
                    frontier.append(link)

            # Be polite
            self._sleep_jitter()

            if len(urls) >= self.config.max_pages:
                break

        return urls

    def _parse_sitemap_for_candidates(self, sitemap_url: str) -> Set[str]:
        """Parse a sitemap.xml and collect candidate URLs."""
        candidates: Set[str] = set()
        try:
            if not self._allowed(sitemap_url):
                self.logger.debug("Sitemap disallowed by robots: %s", sitemap_url)
                return candidates

            self.logger.debug("Fetching sitemap: %s", sitemap_url)
            resp = self.session.get(sitemap_url, timeout=self.config.timeout, verify=self.config.verify_tls)
            if resp.status_code != 200 or not resp.text.strip():
                return candidates

            text = resp.text
            # Extract <loc> elements with a simple regex to avoid full XML parse dependency
            locs = re.findall(r"<loc>(.*?)</loc>", text, flags=re.IGNORECASE | re.DOTALL)
            for loc in locs:
                url = loc.strip()
                if self._is_candidate_url(url):
                    candidates.add(url)
            return candidates
        except requests.RequestException as e:
            self.logger.debug("Sitemap fetch error (%s): %s", sitemap_url, e)
            return candidates
        except Exception as e:
            self.logger.debug("Sitemap parse error (%s): %s", sitemap_url, e)
            return candidates

    def _is_candidate_url(self, url: str) -> bool:
        """Heuristic to identify likely relevant URLs."""
        if not url or any(ex in url.lower() for ex in self.config.url_excludes):
            return False
        if not self.base_domain or not self._same_host(self.base_domain, url):
            return False
        lower = url.lower()
        # Prefer URLs with key terms
        return any(term in lower for term in self.config.url_includes)

    def _is_crawlable(self, url: str) -> bool:
        """Avoid static files and obviously irrelevant endpoints."""
        lower = url.lower()
        if any(lower.endswith(ext) for ext in (".jpg", ".jpeg", ".png", ".gif", ".svg", ".webp", ".css", ".js", ".pdf", ".zip")):
            return False
        if any(bad in lower for bad in self.config.url_excludes):
            return False
        return True

    def _same_host(self, base: str, url: str) -> bool:
        """Check if the URL belongs to the same host as base."""
        try:
            return urlparse(base).netloc == urlparse(url).netloc
        except Exception:
            return False

    def _extract_links(self, base_url: str, html: str) -> Set[str]:
        """Extract and normalize links from a page."""
        links: Set[str] = set()
        try:
            for tag in BeautifulSoup(html, "lxml", parse_only=SoupStrainer("a")):
                if not tag or not tag.has_attr("href"):
                    continue
                href = tag.get("href")
                if not href or href.startswith("#") or href.lower().startswith("javascript:"):
                    continue
                abs_url = urljoin(base_url, href)
                links.add(self._normalize_url(abs_url))
        except Exception:
            # Fallback parser
            for tag in BeautifulSoup(html, "html.parser", parse_only=SoupStrainer("a")):
                if not tag or not tag.has_attr("href"):
                    continue
                href = tag.get("href")
                if not href or href.startswith("#") or href.lower().startswith("javascript:"):
                    continue
                abs_url = urljoin(base_url, href)
                links.add(self._normalize_url(abs_url))
        return links

    def _extract_relevant_sentences(self, urls: Iterable[str]) -> List[Tuple[str, str, List[str]]]:
        """
        Fetch each URL and extract sentences that mention:
          - softwood (core) AND (construction OR furniture) concepts.

        Returns a list of tuples: (page_title, page_url, sentences)
        """
        results: List[Tuple[str, str, List[str]]] = []
        pages_processed = 0

        for url in urls:
            if pages_processed >= self.config.max_pages:
                break
            if not self._allowed(url):
                self.logger.debug("Skipping disallowed URL by robots: %s", url)
                continue

            html = self._safe_get(url)
            if not html:
                continue

            title = self._extract_title(html) or url
            sentences = self._sentences_from_html(html)
            relevant = self._filter_relevant(sentences)

            if relevant:
                results.append((title, url, relevant))

            pages_processed += 1
            self._sleep_jitter()

        return results

    def _extract_title(self, html: str) -> Optional[str]:
        """Extract the <title> text from HTML."""
        try:
            soup = BeautifulSoup(html, "lxml")
        except Exception:
            soup = BeautifulSoup(html, "html.parser")
        title_tag = soup.find("title")
        if title_tag and title_tag.text:
            return self._clean_text(title_tag.text)
        # Try H1 if no title
        h1 = soup.find("h1")
        return self._clean_text(h1.text) if h1 and h1.text else None

    def _sentences_from_html(self, html: str) -> List[str]:
        """Extract text from paragraphs and list items and split into sentences."""
        texts: List[str] = []
        try:
            soup = BeautifulSoup(html, "lxml")
        except Exception:
            soup = BeautifulSoup(html, "html.parser")

        for el in soup.find_all(["p", "li"]):
            if not el.text:
                continue
            text = self._clean_text(el.text)
            if text:
                texts.append(text)

        big_text = " ".join(texts)
        # Basic sentence splitter: split on . ! ? ; and bullet-like separators
        raw_sentences = re.split(r"(?<=[.!?;:])\s+|\s*[\u2022\u2023\u25E6\u2043\u2219]\s*", big_text)
        sentences = [s.strip() for s in raw_sentences if s and len(s.strip()) > 30]
        return sentences

    def _filter_relevant(self, sentences: List[str]) -> List[str]:
        """
        Keep sentences that contain at least one core keyword (softwood) and
        at least one keyword from either construction or furniture categories.
        """
        def has_any(s: str, kws: Iterable[str]) -> bool:
            s_low = s.lower()
            return any(kw in s_low for kw in kws)

        relevant: List[str] = []
        for s in sentences:
            if has_any(s, self.config.core_keywords) and (
                has_any(s, self.config.construction_keywords) or has_any(s, self.config.furniture_keywords)
            ):
                relevant.append(s)

        # Deduplicate while preserving order
        seen = set()
        deduped = []
        for s in relevant:
            if s not in seen:
                seen.add(s)
                deduped.append(s)

        # Limit number of sentences per page to avoid noise
        return deduped[:8]

    def _safe_get(self, url: str) -> Optional[str]:
        """GET a URL safely with retries, timeouts, and errors handled."""
        for attempt in range(1, self.config.connect_retries + 2):
            try:
                self.logger.debug("GET %s (attempt %d)", url, attempt)
                resp = self.session.get(
                    url, timeout=self.config.timeout, allow_redirects=True, verify=self.config.verify_tls
                )
                if 200 <= resp.status_code < 300 and resp.text:
                    return resp.text
                elif 300 <= resp.status_code < 400:
                    # Redirect chains are handled by allow_redirects
                    continue
                elif resp.status_code == 404:
                    self.logger.debug("404 Not Found: %s", url)
                    return None
                else:
                    self.logger.debug("Non-OK status %s for %s", resp.status_code, url)
            except requests.RequestException as e:
                self.logger.debug("Request error for %s: %s", url, e)
            self._sleep_jitter(backoff=attempt)
        return None

    def _sleep_jitter(self, backoff: int = 0) -> None:
        """Polite randomized delay with optional backoff."""
        base = self.config.delay + (0.25 * backoff)
        time.sleep(base + random.uniform(0, 0.25))

    @staticmethod
    def _normalize_url(url: str) -> str:
        """Normalize URL by removing fragments and normalizing scheme/host."""
        parsed = urlparse(url)
        scheme = parsed.scheme or "https"
        netloc = parsed.netloc.lower()
        path = parsed.path or "/"
        return urlunparse((scheme, netloc, path, "", "", ""))

    @staticmethod
    def _clean_text(text: str) -> str:
        """Clean text by collapsing whitespace and stripping."""
        text = re.sub(r"\s+", " ", text or "")
        return text.strip()


def configure_logging(verbose: bool) -> logging.Logger:
    """Configure and return a logger."""
    logger = logging.getLogger("softwood_scraper")
    level = logging.DEBUG if verbose else logging.INFO
    logger.setLevel(level)
    handler = logging.StreamHandler(sys.stderr)
    handler.setLevel(level)
    fmt = logging.Formatter("[%(levelname)s] %(message)s")
    handler.setFormatter(fmt)
    # Avoid duplicate handlers if re-run in same interpreter
    if not logger.handlers:
        logger.addHandler(handler)
    else:
        logger.handlers.clear()
        logger.addHandler(handler)
    return logger


def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
    """Parse CLI arguments."""
    parser = argparse.ArgumentParser(
        description="Retrieve and display softwood lumber information (uses in construction and furniture) from Atilumber."
    )
    parser.add_argument("--domain", type=str, default=None, help="Base domain to use (e.g., https://www.atilumber.com)")
    parser.add_argument("--max-pages", type=int, default=20, help="Maximum pages to fetch for discovery/extraction.")
    parser.add_argument("--delay", type=float, default=1.0, help="Polite delay between requests (seconds).")
    parser.add_argument("--verbose", action="store_true", help="Enable verbose debug logging.")
    parser.add_argument("--no-verify-tls", action="store_true", help="Disable TLS certificate verification.")
    return parser.parse_args(argv)


def main(argv: Optional[List[str]] = None) -> int:
    args = parse_args(argv)
    logger = configure_logging(args.verbose)

    cfg = ScraperConfig(
        base_domains=[args.domain] if args.domain else None or ["https://www.atilumber.com", "https://atilumber.com"],
        delay=args.delay,
        max_pages=max(1, args.max_pages),
        verify_tls=not args.no_verify_tls,
    )

    scraper = SoftwoodInfoScraper(cfg, logger=logger)
    exit_code = scraper.run()
    if exit_code == 0:
        logger.info("Completed successfully.")
    else:
        logger.info("Completed with exit code %d.", exit_code)
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())

/**
 * Fetches market data from Pythshop's API for use in blockchain applications.
 *
 * Notes:
 * - This function is transport-agnostic and works in both Node.js (v18+) and modern browsers.
 * - It supports batching requests, retries with exponential backoff, timeouts, and response validation.
 * - You must provide the API base URL of Pythshop (e.g., https://api.pythshop.example).
 *
 * Example:
 *   const data = await fetchPythshopMarketData(
 *     ['BTC/USD', 'ETH/USD'],
 *     {
 *       baseUrl: 'https://api.pythshop.example',
 *       endpointPath: '/v1/market-data',
 *       apiKey: process.env.PYTHSHOP_API_KEY,
 *     }
 *   );
 *   console.log(data);
 *
 * Production tips:
 * - Always secure your API key (e.g., environment variables).
 * - Consider caching responses if your use case allows.
 * - Tune timeout and retry settings based on your SLAs.
 */

/**
 * @typedef {Object} MarketData
 * @property {string} id - Unique identifier for the market or price feed (e.g., "BTC/USD" or a feed ID).
 * @property {string | undefined} symbol - Optional human-friendly symbol (e.g., "BTC/USD").
 * @property {number} price - Decimal price adjusted by exponent (if provided in the response).
 * @property {string} rawPrice - Raw price as a string for precision-critical use (e.g., big integer string).
 * @property {number | undefined} conf - Confidence interval (if provided).
 * @property {number | undefined} exponent - Exponent to adjust raw price (if provided).
 * @property {number} publishTime - Publish time as a Unix timestamp (seconds).
 * @property {string} publishTimeISO - Publish time as an ISO string.
 */

/**
 * @typedef {Object} FetchOptions
 * @property {string} baseUrl - Base URL for the Pythshop API (e.g., "https://api.pythshop.example").
 * @property {string} [endpointPath="/v1/market-data"] - Path to the market data endpoint.
 * @property {string} [apiKey] - Optional API key for authenticated endpoints.
 * @property {Record<string, string>} [additionalHeaders] - Additional headers to include with requests.
 * @property {number} [timeoutMs=8000] - Timeout per HTTP request in milliseconds.
 * @property {number} [maxRetries=3] - Maximum number of retries on transient errors.
 * @property {number} [initialBackoffMs=300] - Initial backoff delay in milliseconds.
 * @property {number} [maxBackoffMs=5000] - Maximum backoff delay in milliseconds.
 * @property {number} [batchSize=50] - Max number of IDs per request (API dependent).
 * @property {number} [concurrency=4] - Maximum number of concurrent batch requests.
 * @property {(status: number) => boolean} [isRetryableStatus] - Custom retry logic for HTTP status codes.
 */

/**
 * Fetch market data from Pythshop for a list of IDs (e.g., price feed IDs or symbols).
 *
 * @param {string[]} ids - Identifiers for the market data to fetch.
 * @param {FetchOptions} options - Configuration for the fetch behavior.
 * @returns {Promise<MarketData[]>} Array of parsed market data.
 */
export async function fetchPythshopMarketData(ids, options) {
  validateInputs(ids, options);
  const {
    baseUrl,
    endpointPath = '/v1/market-data',
    apiKey,
    additionalHeaders = {},
    timeoutMs = 8000,
    maxRetries = 3,
    initialBackoffMs = 300,
    maxBackoffMs = 5000,
    batchSize = 50,
    concurrency = 4,
    isRetryableStatus = (status) => status === 408 || status === 429 || (status >= 500 && status < 600),
  } = options;

  const normalizedBaseUrl = stripTrailingSlash(baseUrl);
  const normalizedPath = ensureLeadingSlash(endpointPath);

  const batches = chunk(ids, batchSize);
  const results = [];
  const errors = [];

  // Simple concurrency control
  const queue = [...batches];
  const workers = Array.from({ length: Math.min(concurrency, queue.length) }, () =>
    (async function worker() {
      while (queue.length > 0) {
        const batch = queue.shift();
        if (!batch || batch.length === 0) continue;
        try {
          const url = buildUrl(normalizedBaseUrl, normalizedPath, { ids: batch });
          const responseJson = await httpGetWithRetry(url, {
            headers: buildHeaders(apiKey, additionalHeaders),
            timeoutMs,
            maxRetries,
            initialBackoffMs,
            maxBackoffMs,
            isRetryableStatus,
          });
          const parsed = parseMarketDataResponse(responseJson);
          results.push(...parsed);
        } catch (err) {
          errors.push({ batch, error: toError(err) });
        }
      }
    })()
  );

  await Promise.all(workers);

  if (errors.length > 0 && results.length === 0) {
    // If all batches failed, surface the first error
    const first = errors[0];
    const message = `Failed to fetch market data for all batches. Example failure for [${(first.batch || []).join(', ')}]: ${first.error.message}`;
    const aggregate = new Error(message);
    aggregate.name = 'PythshopFetchError';
    // Attach details for observability
    aggregate.details = { errors };
    throw aggregate;
  }

  // Deduplicate by id (last write wins)
  const deduped = dedupeBy(results, (x) => x.id);
  return deduped;
}

/**
 * Validate function inputs early to fail-fast.
 * @param {string[]} ids
 * @param {FetchOptions} options
 */
function validateInputs(ids, options) {
  if (!Array.isArray(ids) || ids.length === 0) {
    throw new TypeError('ids must be a non-empty array of strings.');
  }
  if (ids.some((id) => typeof id !== 'string' || id.trim().length === 0)) {
    throw new TypeError('Each id in ids must be a non-empty string.');
  }
  if (!options || typeof options !== 'object') {
    throw new TypeError('options must be provided as an object.');
  }
  if (!options.baseUrl || typeof options.baseUrl !== 'string') {
    throw new TypeError('options.baseUrl must be a non-empty string.');
  }
}

/**
 * Build the request URL with query parameters.
 * Expected API: GET {baseUrl}{endpointPath}?ids=ID1,ID2,...
 *
 * @param {string} baseUrl
 * @param {string} path
 * @param {{ ids: string[] }} query
 * @returns {string}
 */
function buildUrl(baseUrl, path, query) {
  const url = new URL(path, baseUrl);
  if (query && Array.isArray(query.ids) && query.ids.length > 0) {
    url.searchParams.set('ids', query.ids.map(encodeURIComponent).join(','));
  }
  return url.toString();
}

/**
 * Build standard headers with optional API key and custom headers.
 *
 * @param {string | undefined} apiKey
 * @param {Record<string, string>} additionalHeaders
 * @returns {Record<string, string>}
 */
function buildHeaders(apiKey, additionalHeaders) {
  const headers = {
    Accept: 'application/json',
    'Content-Type': 'application/json',
    ...additionalHeaders,
  };

  // Common patterns for API auth; adjust based on Pythshop's actual requirements.
  if (apiKey && !headers.Authorization && !headers['X-API-Key']) {
    headers.Authorization = `Bearer ${apiKey}`;
  }

  return headers;
}

/**
 * Robust HTTP GET with timeout, retries, exponential backoff + jitter.
 *
 * @param {string} url
 * @param {{
 *   headers?: Record<string, string>,
 *   timeoutMs: number,
 *   maxRetries: number,
 *   initialBackoffMs: number,
 *   maxBackoffMs: number,
 *   isRetryableStatus: (status: number) => boolean
 * }} opts
 * @returns {Promise<any>}
 */
async function httpGetWithRetry(url, opts) {
  const {
    headers = {},
    timeoutMs,
    maxRetries,
    initialBackoffMs,
    maxBackoffMs,
    isRetryableStatus,
  } = opts;

  let attempt = 0;
  let lastError;

  while (attempt <= maxRetries) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const res = await fetch(url, {
        method: 'GET',
        headers,
        signal: controller.signal,
        cache: 'no-store',
      });

      if (!res.ok) {
        // Retry on retryable statuses
        if (isRetryableStatus(res.status) && attempt < maxRetries) {
          attempt++;
          await delay(backoffWithJitter(attempt, initialBackoffMs, maxBackoffMs));
          continue;
        }

        // Non-retryable error or retries exhausted
        const bodyText = await safeReadText(res);
        const err = new Error(`HTTP ${res.status} ${res.statusText}: ${truncate(bodyText, 512)}`);
        err.name = 'HttpError';
        err.status = res.status;
        throw err;
      }

      // Attempt JSON parsing
      const data = await res.json();
      return data;
    } catch (err) {
      const e = toError(err);
      lastError = e;

      // AbortError or network errors may be retryable
      const isAbort = e.name === 'AbortError' || /aborted/i.test(e.message || '');
      const isNetwork = /network/i.test(e.message || '') || e.name === 'TypeError';

      if ((isAbort || isNetwork) && attempt < maxRetries) {
        attempt++;
        await delay(backoffWithJitter(attempt, initialBackoffMs, maxBackoffMs));
        continue;
      }

      // Exhausted or non-retryable error
      throw e;
    } finally {
      clearTimeout(timeout);
    }
  }

  // Should never reach here due to throws in loop
  throw lastError || new Error('Unknown error during HTTP GET with retry');
}

/**
 * Parse and normalize the market data response into a consistent schema.
 * This function is defensive: it tolerates minor schema differences by attempting
 * to map common field names.
 *
 * Expected flexible input item shape, e.g.:
 * {
 *   "id": "BTC/USD",
 *   "symbol": "BTC/USD",
 *   "price": "6800012345",        // string or number
 *   "price_raw": "6800012345",    // alt field
 *   "conf": 12345,                // optional
 *   "exponent": -8,               // optional
 *   "publish_time": 1720000000    // seconds or ms
 * }
 *
 * @param {any} json
 * @returns {MarketData[]}
 */
function parseMarketDataResponse(json) {
  if (!json) return [];

  const asArray = Array.isArray(json) ? json : (Array.isArray(json.data) ? json.data : [json]);

  /** @type {MarketData[]} */
  const output = [];

  for (const item of asArray) {
    try {
      const parsed = parseMarketDataItem(item);
      if (parsed) output.push(parsed);
    } catch (err) {
      // Skip invalid items, but in production you may want to log or collect these
      // console.warn('Skipping invalid market item:', err);
    }
  }

  return output;
}

/**
 * Parse a single market item into MarketData.
 *
 * @param {any} item
 * @returns {MarketData | null}
 */
function parseMarketDataItem(item) {
  if (!item || typeof item !== 'object') {
    throw new TypeError('Market item is not an object');
  }

  // Tolerate varied field names
  const id = strOrUndefined(item.id) || strOrUndefined(item.feed_id) || strOrUndefined(item.symbol) || null;
  if (!id) throw new TypeError('Market item is missing an id/symbol');

  const symbol = strOrUndefined(item.symbol) || strOrUndefined(item.ticker);

  const rawPrice =
    strOrUndefined(item.rawPrice) ||
    strOrUndefined(item.price_raw) ||
    strOrUndefined(item.price) ||
    (typeof item.price === 'number' ? String(item.price) : undefined);

  if (!rawPrice) {
    throw new TypeError(`Market item for ${id} missing price/rawPrice`);
  }

  const exponent =
    numberOrUndefined(item.exponent) ??
    numberOrUndefined(item.price_exponent) ??
    inferExponentFromPrice(rawPrice);

  // Adjusted decimal price; if exponent is undefined, attempt reasonable parsing
  const price = toAdjustedDecimal(rawPrice, exponent);

  const conf =
    numberOrUndefined(item.conf) ??
    numberOrUndefined(item.confidence) ??
    numberOrUndefined(item.price_conf);

  // Publish time could be in seconds or milliseconds
  const pt =
    numberOrUndefined(item.publish_time) ??
    numberOrUndefined(item.timestamp) ??
    numberOrUndefined(item.publishTime);

  const publishTime = normalizeUnixSeconds(pt);
  const publishTimeISO = new Date(publishTime * 1000).toISOString();

  return {
    id,
    symbol,
    price,
    rawPrice,
    conf,
    exponent,
    publishTime,
    publishTimeISO,
  };
}

/**
 * Utilities
 */

function stripTrailingSlash(s) {
  return s.replace(/\/+$/, '');
}

function ensureLeadingSlash(s) {
  return s.startsWith('/') ? s : `/${s}`;
}

/**
 * Chunk an array into fixed-size batches.
 * @template T
 * @param {T[]} arr
 * @param {number} size
 * @returns {T[][]}
 */
function chunk(arr, size) {
  if (!Number.isFinite(size) || size <= 0) return [arr.slice()];
  const out = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

/**
 * Deduplicate by a key function (last occurrence wins).
 * @template T
 * @param {T[]} arr
 * @param {(x: T) => string} keyFn
 * @returns {T[]}
 */
function dedupeBy(arr, keyFn) {
  const map = new Map();
  for (const item of arr) {
    map.set(keyFn(item), item);
  }
  return Array.from(map.values());
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Exponential backoff with full jitter.
 * @param {number} attempt - Attempt number starting from 1
 * @param {number} baseMs - Initial backoff
 * @param {number} capMs - Maximum backoff
 * @returns {number}
 */
function backoffWithJitter(attempt, baseMs, capMs) {
  const exp = Math.min(capMs, baseMs * Math.pow(2, Math.max(0, attempt - 1)));
  return Math.floor(Math.random() * exp); // full jitter
}

/**
 * Safely read response text (best-effort).
 * @param {Response} res
 * @returns {Promise<string>}
 */
async function safeReadText(res) {
  try {
    return await res.text();
  } catch {
    return '';
  }
}

function truncate(s, max) {
  if (typeof s !== 'string') return '';
  return s.length > max ? s.slice(0, max) + '…' : s;
}

function toError(err) {
  if (err instanceof Error) return err;
  return new Error(typeof err === 'string' ? err : JSON.stringify(err));
}

function strOrUndefined(x) {
  return typeof x === 'string' && x.length > 0 ? x : undefined;
}

function numberOrUndefined(x) {
  return typeof x === 'number' && Number.isFinite(x) ? x : undefined;
}

/**
 * Attempt to infer exponent if not provided.
 * This is a best-effort guess, typically unnecessary if the API provides exponent.
 * @param {string} rawPrice
 * @returns {number | undefined}
 */
function inferExponentFromPrice(rawPrice) {
  // Heuristic: if it's a large integer string, assume exponent -8 (common for Pyth-like feeds).
  if (/^\d+$/.test(rawPrice) && rawPrice.length > 4) {
    return -8;
  }
  return undefined;
}

/**
 * Convert a raw integer-like price string and exponent into a decimal number.
 * If exponent is undefined, parse as float safely.
 * @param {string} rawPrice
 * @param {number | undefined} exponent
 * @returns {number}
 */
function toAdjustedDecimal(rawPrice, exponent) {
  // For high precision, consider returning a BigInt or a decimal library in production.
  if (typeof exponent === 'number' && Number.isInteger(exponent)) {
    // Adjust by 10^exponent
    const exp = exponent;
    if (exp === 0) return Number(rawPrice);

    const negative = rawPrice.startsWith('-');
    const digits = negative ? rawPrice.slice(1) : rawPrice;

    if (!/^\d+$/.test(digits)) {
      // Fallback to float parse
      return Number(rawPrice);
    }

    if (exp > 0) {
      // Append zeros
      const val = digits + '0'.repeat(exp);
      return Number((negative ? '-' : '') + val);
    } else {
      // Insert decimal point
      const pos = digits.length + exp; // exp is negative
      if (pos > 0) {
        const val = digits.slice(0, pos) + '.' + digits.slice(pos);
        return Number((negative ? '-' : '') + val);
      } else {
        const zeros = '0'.repeat(Math.abs(pos));
        const val = '0.' + zeros + digits;
        return Number((negative ? '-' : '') + val);
      }
    }
  }

  // No exponent provided; attempt float conversion
  const n = Number(rawPrice);
  if (!Number.isFinite(n)) {
    throw new TypeError(`Invalid price value: ${rawPrice}`);
  }
  return n;
}

/**
 * Normalize timestamps to Unix seconds.
 * Accepts undefined, seconds, or milliseconds.
 * @param {number | undefined} t
 * @returns {number}
 */
function normalizeUnixSeconds(t) {
  const nowSecs = Math.floor(Date.now() / 1000);
  if (typeof t !== 'number' || !Number.isFinite(t) || t <= 0) return nowSecs;
  // If it's in milliseconds (e.g., > 10^12), convert to seconds
  return t > 1e12 ? Math.floor(t / 1000) : Math.floor(t);
}

#!/usr/bin/env python3
"""
Automate the purchase of a VCC card from SimpleVCC using an assumed REST API.

Important:
- This script assumes SimpleVCC provides a legitimate public API that you are authorized to use.
- Do not scrape the website or bypass anti-bot/verification systems.
- Always follow the platform's Terms of Service and applicable laws.
- Never log or expose full card data. This script redacts sensitive information by default.

Configuration:
- Environment variables (preferred):
    SIMPLEVCC_API_BASE_URL=https://api.simplevcc.example/v1
    SIMPLEVCC_API_KEY=your_api_key_here
- Or via CLI flags --api-base-url and --api-key

Usage examples:
    python3 purchase_vcc.py --amount 25 --currency USD --product-name "Standard VCC" --output-file vcc.json
    python3 purchase_vcc.py --amount 50 --currency EUR --product-id prod_123

Notes:
- Endpoints and response schemas are placeholders; adjust to the actual SimpleVCC API.
- The script is production-oriented with retries, timeouts, logging, and careful handling of sensitive data.
"""

from __future__ import annotations

import argparse
import json
import logging
import os
import random
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Optional, Tuple
from urllib.parse import urljoin

import requests
from requests import Response, Session
from requests.exceptions import HTTPError, RequestException, Timeout


# -------------------------- Exceptions -------------------------- #


class SimpleVCCError(Exception):
    """Base exception for SimpleVCC client errors."""


class SimpleVCCAuthError(SimpleVCCError):
    """Authentication or authorization error."""


class SimpleVCCRateLimitError(SimpleVCCError):
    """Rate limiting encountered after exhaustive retries."""


class SimpleVCCNotFoundError(SimpleVCCError):
    """Resource not found."""


class SimpleVCCValidationError(SimpleVCCError):
    """Invalid request or parameters."""


class SimpleVCCAPIError(SimpleVCCError):
    """Generic API error."""


# -------------------------- Configuration -------------------------- #


@dataclass(frozen=True)
class Config:
    api_base_url: str
    api_key: str
    request_timeout: float = 30.0  # seconds
    max_retries: int = 5
    backoff_base: float = 0.75  # base delay for backoff
    backoff_jitter: float = 0.3  # random jitter to avoid thundering herd


# -------------------------- Utilities -------------------------- #


def mask_pan(pan: str) -> str:
    """Mask a Primary Account Number (PAN) leaving only last 4 digits visible."""
    if not pan:
        return ""
    stripped = "".join(ch for ch in pan if ch.isdigit())
    if len(stripped) <= 4:
        return stripped
    return "**** **** **** " + stripped[-4:]


def redact_card_payload(data: Any) -> Any:
    """
    Recursively redact sensitive card details in an object, preserving structure.
    - pan / card_number -> masked
    - cvv / cvc -> '***'
    - expiry -> partially redacted
    - token -> hashed-like placeholder
    """
    if isinstance(data, dict):
        redacted: Dict[str, Any] = {}
        for k, v in data.items():
            lk = k.lower()
            if lk in {"pan", "card_number", "number"} and isinstance(v, str):
                redacted[k] = mask_pan(v)
            elif lk in {"cvv", "cvc", "cvv2"} and isinstance(v, str):
                redacted[k] = "***"
            elif lk in {"expiry", "exp", "exp_date", "expiration"} and isinstance(v, (str, dict)):
                if isinstance(v, dict):
                    month = str(v.get("month", "MM")).zfill(2)
                    year = str(v.get("year", "YYYY"))
                    redacted[k] = f"{month}/{year[-2:] if year != 'YYYY' else 'YY'}"
                else:
                    redacted[k] = v[:2] + "/**"
            elif lk in {"token", "card_token"} and isinstance(v, str):
                redacted[k] = f"tok_{hash(v) & 0xFFFFFFFF:08x}"
            else:
                redacted[k] = redact_card_payload(v)
        return redacted
    if isinstance(data, list):
        return [redact_card_payload(x) for x in data]
    return data


def secure_write_json(path: Path, data: Dict[str, Any]) -> None:
    """
    Write JSON to a file with restrictive permissions to minimize exposure risk.
    Warning: Storing raw card data may be subject to compliance requirements (e.g., PCI DSS).
    """
    try:
        # Ensure parent directory exists
        path.parent.mkdir(parents=True, exist_ok=True)

        # Open with restrictive permissions (0600)
        # On Windows, this won't fully emulate POSIX permissions; further ACL hardening may be needed.
        with os.fdopen(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.write("\n")
    except OSError as e:
        raise SimpleVCCError(f"Failed to write JSON to {path}: {e}") from e


def normalize_currency(code: str) -> str:
    """Normalize currency code to uppercase 3-letter ISO format."""
    code = (code or "").strip().upper()
    if len(code) != 3:
        raise ValueError("Currency must be a 3-letter ISO code, e.g., USD, EUR.")
    return code


# -------------------------- HTTP Client -------------------------- #


class HTTPClient:
    """
    Minimal HTTP client with retry, timeout, and structured error handling.
    """

    def __init__(self, config: Config, logger: logging.Logger) -> None:
        self._config = config
        self._session: Session = Session()
        self._session.headers.update({
            "Authorization": f"Bearer {config.api_key}",
            "Accept": "application/json",
            "Content-Type": "application/json",
            "User-Agent": "simplevcc-client/1.0 (+https://example.com)",
        })
        self._logger = logger.getChild("HTTP")

    def request(self, method: str, path: str, *, params: Optional[Dict[str, Any]] = None,
                json_body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """
        Send an HTTP request with retry/backoff for transient errors.
        Raises appropriate SimpleVCCError on failure.
        """
        url = urljoin(self._config.api_base_url.rstrip("/") + "/", path.lstrip("/"))
        attempt = 0
        last_error: Optional[Exception] = None

        while attempt < self._config.max_retries:
            attempt += 1
            try:
                self._logger.debug("HTTP %s %s (attempt %d) params=%s body=%s",
                                   method, url, attempt, params, redact_card_payload(json_body))
                resp: Response = self._session.request(
                    method=method.upper(),
                    url=url,
                    params=params,
                    json=json_body,
                    timeout=self._config.request_timeout,
                )

                # Handle rate limit and server errors with backoff
                if resp.status_code in (429, 502, 503, 504):
                    retry_after = self._compute_backoff(attempt, resp)
                    self._logger.warning("Transient HTTP %s received (status=%d). Backing off for %.2fs.",
                                         "rate limit" if resp.status_code == 429 else "server error",
                                         resp.status_code, retry_after)
                    self._sleep(retry_after)
                    continue

                # Raise for non-2xx
                try:
                    resp.raise_for_status()
                except HTTPError as e:
                    self._handle_http_error(resp, e)

                # Parse JSON safely
                try:
                    payload = resp.json()
                except ValueError:
                    payload = {"raw": resp.text}
                self._logger.debug("HTTP response status=%d payload=%s", resp.status_code, redact_card_payload(payload))
                return payload

            except (Timeout, RequestException) as e:
                last_error = e
                backoff = self._compute_backoff(attempt)
                self._logger.warning("Request error: %s. Retrying in %.2fs (%d/%d)", e, backoff, attempt, self._config.max_retries)
                self._sleep(backoff)

        # Exhausted retries
        if isinstance(last_error, HTTPError):
            raise SimpleVCCAPIError(f"HTTP error after retries: {last_error}") from last_error
        if isinstance(last_error, Timeout):
            raise SimpleVCCAPIError("Request timed out after retries.") from last_error
        if isinstance(last_error, RequestException):
            raise SimpleVCCAPIError(f"Request failed after retries: {last_error}") from last_error
        raise SimpleVCCRateLimitError("Exhausted retries due to rate limits or server errors.")

    def _compute_backoff(self, attempt: int, resp: Optional[Response] = None) -> float:
        """Compute exponential backoff with jitter; respect Retry-After header if present."""
        if resp is not None:
            retry_after_hdr = resp.headers.get("Retry-After")
            if retry_after_hdr:
                try:
                    ra = float(retry_after_hdr)
                    return max(ra, 0.1)
                except ValueError:
                    pass
        base = self._config.backoff_base * (2 ** (attempt - 1))
        jitter = random.uniform(0, self._config.backoff_jitter)
        return min(30.0, base + jitter)

    @staticmethod
    def _sleep(seconds: float) -> None:
        time.sleep(max(0.0, seconds))

    def _handle_http_error(self, resp: Response, error: HTTPError) -> None:
        """Raise an appropriate domain-specific error based on HTTP status and payload."""
        status = resp.status_code
        try:
            payload = resp.json()
        except ValueError:
            payload = {"raw": resp.text or ""}
        message = (payload.get("message")
                   or payload.get("error", {}).get("message")
                   or payload.get("error_description")
                   or resp.reason
                   or "API error")

        if status in (401, 403):
            raise SimpleVCCAuthError(f"Auth error ({status}): {message}") from error
        if status == 404:
            raise SimpleVCCNotFoundError(f"Not found: {message}") from error
        if status == 400:
            raise SimpleVCCValidationError(f"Validation error: {message}") from error

        raise SimpleVCCAPIError(f"API error ({status}): {message}") from error


# -------------------------- SimpleVCC API Wrapper -------------------------- #


class SimpleVCCClient:
    """
    Thin wrapper over the assumed SimpleVCC REST API.
    Adjust endpoints and payloads to match the actual API.
    """

    def __init__(self, http: HTTPClient, logger: logging.Logger) -> None:
        self._http = http
        self._logger = logger.getChild("Client")

    def verify_credentials(self) -> Dict[str, Any]:
        """Fetch account/profile to verify the API key works."""
        return self._http.request("GET", "/account")

    def list_products(self, product_type: str = "vcc") -> Dict[str, Any]:
        """List available VCC products."""
        return self._http.request("GET", "/products", params={"type": product_type})

    def create_order(self, *, product_id: str, currency: str, amount: float, note: Optional[str] = None) -> Dict[str, Any]:
        """Create a VCC order."""
        payload = {
            "product_id": product_id,
            "currency": currency,
            "amount": amount,
        }
        if note:
            payload["note"] = note
        return self._http.request("POST", "/orders", json_body=payload)

    def get_order(self, order_id: str) -> Dict[str, Any]:
        """Get order status/details."""
        return self._http.request("GET", f"/orders/{order_id}")

    def get_card(self, card_id: str) -> Dict[str, Any]:
        """
        Fetch card details for a created VCC.
        Note: Access to full PAN/CVV may be restricted; API may return tokenized data or require privileged scopes.
        """
        return self._http.request("GET", f"/cards/{card_id}")


# -------------------------- Core Flow -------------------------- #


def find_product_id_by_name(products_payload: Dict[str, Any], desired_name: str) -> Optional[str]:
    """
    Find product_id by case-insensitive name match. Adjust this logic based on actual schema.
    Expected schema example:
    { "data": [ { "id": "prod_123", "name": "Standard VCC", ... }, ... ] }
    """
    items = products_payload.get("data") or products_payload.get("items") or []
    for item in items:
        name = str(item.get("name", "")).strip().lower()
        if name == desired_name.strip().lower():
            return str(item.get("id"))
    # Attempt partial match
    for item in items:
        name = str(item.get("name", "")).strip().lower()
        if desired_name.strip().lower() in name:
            return str(item.get("id"))
    return None


def extract_order_status(order_payload: Dict[str, Any]) -> Tuple[str, Optional[str]]:
    """
    Extract order status and card_id if available from an order payload.
    This function is defensive and supports a few common schema shapes.
    """
    status = str(order_payload.get("status") or order_payload.get("state") or "unknown").lower()
    card_id = None

    # Common possibilities for where the card ID may reside
    if "card_id" in order_payload:
        card_id = str(order_payload["card_id"])
    elif "card" in order_payload and isinstance(order_payload["card"], dict):
        card_id = str(order_payload["card"].get("id") or order_payload["card"].get("card_id") or "")
        if not card_id:
            # Sometimes card details are nested differently
            id_candidates = [order_payload["card"].get("id"), order_payload["card"].get("cardId")]
            card_id = next((str(x) for x in id_candidates if x), None)

    return status, card_id


def is_final_status(status: str) -> bool:
    """Return True if the order status is final (success or failure)."""
    finals = {"completed", "issued", "delivered", "active", "failed", "cancelled", "canceled", "declined", "error"}
    return status.lower() in finals


def is_success_status(status: str) -> bool:
    """Return True if the order status indicates success."""
    successes = {"completed", "issued", "delivered", "active"}
    return status.lower() in successes


def purchase_vcc(
    client: SimpleVCCClient,
    *,
    product_id: str,
    currency: str,
    amount: float,
    note: Optional[str],
    poll_timeout: float,
    poll_interval: float,
    logger: logging.Logger,
) -> Dict[str, Any]:
    """
    Create a VCC order and poll until it reaches a final status, then fetch card details if available.
    Returns a dictionary with order and (redacted) card info.
    """
    order = client.create_order(product_id=product_id, currency=currency, amount=amount, note=note)
    order_id = str(order.get("id") or order.get("order_id") or "")
    if not order_id:
        raise SimpleVCCAPIError("API did not return an order ID.")

    logger.info("Order created: %s", order_id)
    start = time.time()
    last_status = None

    while True:
        if time.time() - start > poll_timeout:
            raise SimpleVCCError(f"Polling timed out after {int(poll_timeout)}s. Last status: {last_status or 'unknown'}")

        current = client.get_order(order_id)
        status, card_id = extract_order_status(current)
        last_status = status
        logger.info("Order %s status: %s", order_id, status)

        if is_final_status(status):
            result: Dict[str, Any] = {
                "order": current,
                "status": status,
            }
            if is_success_status(status):
                # Attempt to fetch card details if an ID is available
                card_payload: Optional[Dict[str, Any]] = None
                if card_id:
                    try:
                        card_payload = client.get_card(card_id)
                    except SimpleVCCError as e:
                        logger.warning("Unable to fetch card details by id=%s: %s", card_id, e)
                else:
                    # Some APIs return card details inline within the order
                    inline_card = current.get("card") or current.get("card_details") or None
                    if isinstance(inline_card, dict):
                        card_payload = inline_card

                if card_payload:
                    # Redact sensitive fields before returning or logging
                    safe_card = redact_card_payload(card_payload)
                    result["card"] = safe_card
                else:
                    logger.info("Card details not available in the API response.")
            else:
                logger.error("Order ended in a non-successful status: %s", status)
            return result

        time.sleep(poll_interval)


# -------------------------- CLI -------------------------- #


def build_arg_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        description="Automate purchase of a VCC card from SimpleVCC via its API.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    p.add_argument("--api-base-url", default=os.getenv("SIMPLEVCC_API_BASE_URL", "").strip(),
                   help="Base URL for the SimpleVCC API (e.g., https://api.simplevcc.example/v1)")
    p.add_argument("--api-key", default=os.getenv("SIMPLEVCC_API_KEY", "").strip(),
                   help="API key or token for SimpleVCC")

    product = p.add_mutually_exclusive_group(required=True)
    product.add_argument("--product-id", help="Product ID to purchase")
    product.add_argument("--product-name", help="Product name to match (exact or partial)")

    p.add_argument("--amount", type=float, required=True, help="Amount to load onto the VCC")
    p.add_argument("--currency", type=str, required=True, help="Currency code (e.g., USD, EUR)")
    p.add_argument("--note", type=str, default=None, help="Optional note/metadata for the order")
    p.add_argument("--poll-timeout", type=float, default=180.0, help="Max seconds to wait for order completion")
    p.add_argument("--poll-interval", type=float, default=3.0, help="Seconds between status polls")
    p.add_argument("--output-file", type=str, default=None, help="Path to write the redacted result JSON")
    p.add_argument("--dry-run", action="store_true", help="Validate setup and resolve product only; do not place an order")
    p.add_argument("--log-level", default=os.getenv("LOG_LEVEL", "INFO"), choices=["DEBUG", "INFO", "WARNING", "ERROR"], help="Logging verbosity")
    return p


def setup_logger(level: str) -> logging.Logger:
    logger = logging.getLogger("simplevcc")
    logger.setLevel(getattr(logging, level.upper(), logging.INFO))
    handler = logging.StreamHandler(sys.stdout)
    fmt = logging.Formatter(fmt="%(asctime)s %(levelname)s %(name)s: %(message)s", datefmt="%Y-%m-%d %H:%M:%S")
    handler.setFormatter(fmt)
    logger.handlers.clear()
    logger.addHandler(handler)
    return logger


def validate_config(args: argparse.Namespace) -> Config:
    api_base_url = (args.api_base_url or "").strip()
    api_key = (args.api_key or "").strip()

    if not api_base_url:
        raise SimpleVCCError("API base URL is required. Set SIMPLEVCC_API_BASE_URL or pass --api-base-url.")
    if not api_key:
        raise SimpleVCCError("API key is required. Set SIMPLEVCC_API_KEY or pass --api-key.")
    if not api_base_url.startswith("http"):
        raise SimpleVCCError("API base URL must start with http or https.")

    try:
        currency = normalize_currency(args.currency)
        setattr(args, "currency", currency)
    except ValueError as e:
        raise SimpleVCCError(str(e)) from e

    if args.amount <= 0:
        raise SimpleVCCError("Amount must be greater than 0.")

    return Config(
        api_base_url=api_base_url.rstrip("/"),
        api_key=api_key,
        request_timeout=30.0,
        max_retries=5,
        backoff_base=0.75,
        backoff_jitter=0.35,
    )


def main() -> int:
    parser = build_arg_parser()
    args = parser.parse_args()
    logger = setup_logger(args.log_level)

    try:
        config = validate_config(args)
    except SimpleVCCError as e:
        logger.error("Configuration error: %s", e)
        return 2

    http = HTTPClient(config, logger)
    client = SimpleVCCClient(http, logger)

    # Verify credentials
    try:
        acct = client.verify_credentials()
        safe_acct = redact_card_payload(acct)
        logger.info("Authenticated with SimpleVCC. Account: %s", json.dumps(safe_acct))
    except SimpleVCCAuthError as e:
        logger.error("Authentication failed: %s", e)
        return 3
    except SimpleVCCError as e:
        logger.error("Failed to verify credentials: %s", e)
        return 3

    # Resolve product ID if needed
    product_id = args.product_id
    if not product_id and args.product_name:
        try:
            products = client.list_products("vcc")
        except SimpleVCCError as e:
            logger.error("Unable to list products: %s", e)
            return 4

        resolved = find_product_id_by_name(products, args.product_name)
        if not resolved:
            logger.error("Could not find product matching name: %s", args.product_name)
            items = products.get("data") or products.get("items") or []
            if items:
                logger.info("Available products:")
                for it in items:
                    logger.info("- %s (%s)", it.get("name", "unknown"), it.get("id", "n/a"))
            return 4
        product_id = resolved
        logger.info("Resolved product '%s' to ID: %s", args.product_name, product_id)

    # Dry run mode
    if args.dry_run:
        logger.info("Dry run: would create order with product_id=%s amount=%.2f %s note=%s",
                    product_id, args.amount, args.currency, args.note or "")
        return 0

    # Execute purchase flow
    try:
        result = purchase_vcc(
            client,
            product_id=product_id,
            currency=args.currency,
            amount=args.amount,
            note=args.note,
            poll_timeout=args.poll_timeout,
            poll_interval=args.poll_interval,
            logger=logger,
        )
    except SimpleVCCValidationError as e:
        logger.error("Validation error during purchase: %s", e)
        return 5
    except SimpleVCCNotFoundError as e:
        logger.error("Resource not found during purchase: %s", e)
        return 5
    except SimpleVCCAuthError as e:
        logger.error("Authorization error during purchase: %s", e)
        return 5
    except SimpleVCCRateLimitError as e:
        logger.error("Rate limit exceeded during purchase: %s", e)
        return 5
    except SimpleVCCError as e:
        logger.error("Purchase failed: %s", e)
        return 5

    # Redact sensitive data and output
    safe_output = {
        "status": result.get("status"),
        "order": redact_card_payload(result.get("order")),
        "card": redact_card_payload(result.get("card")) if result.get("card") else None,
    }

    # Log minimal info to avoid leaking secrets
    logger.info("Purchase flow completed with status: %s", safe_output.get("status"))
    if args.output_file:
        try:
            secure_write_json(Path(args.output_file), safe_output)
            logger.info("Redacted result written to %s", args.output_file)
        except SimpleVCCError as e:
            logger.error("Failed to write output file: %s", e)
            return 6
    else:
        # Print redacted JSON to stdout
        print(json.dumps(safe_output, indent=2, ensure_ascii=False))

    # Non-zero exit for non-success statuses to help automation pipelines detect failures
    if not is_success_status(str(safe_output.get("status") or "")):
        return 7

    return 0


