    const n = Number(raw);
    if (!Number.isFinite(n)) throw new Error(`Invalid number for ${name}: ${raw}`);
    if (min != null && n < min) throw new Error(`Value for ${name} below min ${min}`);
    if (max != null && n > max) throw new Error(`Value for ${name} above max ${max}`);
