    // Summary/Excerpt
    const summaryEl = $el.find('.excerpt, .summary, .desc, .description, p').first();
    const summary = (summaryEl.text() || '').replace(/\s+/g, ' ').trim();

    // Date
    const date = extractDateFromElement($el);

    articles.push({
      title,
      url: absLink,
      date,
      summary
