    // ====================== Trading Engine ======================

    static final class TradingEngine {
        private final TradingConfig cfg;
        private final MarketDataService dataService;
        private final Strategy strategy;
        private final OrderService orderService;
        private final Logger log;

        private final ScheduledExecutorService scheduler;
        private volatile boolean running = false;

        private List<Candle> candles = new ArrayList<>();

        TradingEngine(TradingConfig cfg, MarketDataService dataService, Strategy strategy, OrderService orderService, Logger log) {
            this.cfg = cfg;
            this.dataService = dataService;
            this.strategy = strategy;
            this.orderService = orderService;
            this.log = log;
            this.scheduler = Executors.newSingleThreadScheduledExecutor(new NamedThreadFactory("trading-engine"));
        }

        void start() {
            candles = dataService.loadHistory();
            running = true;
            scheduler.scheduleAtFixedRate(this::tick, 1, cfg.engineTick.getSeconds(), TimeUnit.SECONDS);
            log.info("Trading engine started.");
        }

        void stop() {
            running = false;
            scheduler.shutdown();
            try {
                if (!scheduler.awaitTermination(5, TimeUnit.SECONDS)) {
                    scheduler.shutdownNow();
                }
            } catch (InterruptedException e) {
                scheduler.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }

        private void tick() {
            if (!running) return;
            try {
                refreshData();
                if (candles.isEmpty()) {
                    log.warning("No candles to evaluate.");
                    return;
                }

                Candle last = candles.get(candles.size() - 1);
                StrategyDecision decision = strategy.decide(candles);
                Optional<Position> openPosOpt = dataService.getOpenPosition();

                log.fine(() -> String.format(Locale.US, "Tick at %s | Price=%s | Decision=%s (%s)",
                        ZonedDateTime.ofInstant(last.time, ZoneOffset.UTC), last.close, decision.signal, decision.reason));

                if (decision.signal == StrategySignal.BUY && openPosOpt.isEmpty()) {
                    RiskDecision rd = ((DefaultRiskManager) ((TrendFollowingStrategy) strategy).risk).assess(candles, decision.signal, last.close);
                    if (!rd.allowTrade) {
                        log.info("Trade blocked by risk: " + rd.reason);
                        return;
                    }
                    orderService.marketBuy(rd.quantity, "entry-long");
                    Position pos = new Position(cfg.symbol, OrderSide.BUY, last.close, rd.quantity, rd.stopLoss, rd.takeProfit, Instant.now());
                    // Store position in client (paper) or synchronize with live OCO orders
                    try {
                        orderService.client.setOpenPosition(pos);
                    } catch (Exception e) {
                        log.log(Level.WARNING, "Failed to set open position", e);
                    }
                    log.info(() -> String.format(Locale.US, "Opened LONG position qty=%s entry=%s SL=%s TP=%s",
                            rd.quantity, last.close, rd.stopLoss, rd.takeProfit));
                } else if ((decision.signal == StrategySignal.SELL || decision.signal == StrategySignal.EXIT) && openPosOpt.isPresent()) {
                    orderService.closePosition();
                    log.info("Closed position due to SELL/EXIT signal.");
                } else {
                    // Manage trailing stops and TP check (paper mode simplification)
                    openPosOpt.ifPresent(pos -> manageStops(pos, last.close));
                }
            } catch (Exception e) {
                log.log(Level.SEVERE, "Engine tick failed", e);
            }
        }

        private void refreshData() {
            try {
                // Reuse historical list and append the latest candle from the client,
                // or reload entire history if the client provides only full snapshots.
                candles = dataService.loadHistory();
            } catch (Exception e) {
                log.log(Level.WARNING, "Failed to refresh data", e);
            }
        }

        private void manageStops(Position pos, BigDecimal lastPrice) {
            try {
                // Take-profit
                if (pos.takeProfit != null && lastPrice.compareTo(pos.takeProfit) >= 0) {
                    log.info(() -> "Take-profit reached at price " + lastPrice + ", closing position.");
                    orderService.closePosition();
                    return;
                }
                // Stop-loss
                if (pos.stopLoss != null && lastPrice.compareTo(pos.stopLoss) <= 0) {
                    log.info(() -> "Stop-loss hit at price " + lastPrice + ", closing position.");
                    orderService.closePosition();
                }
            } catch (Exception e) {
                log.log(Level.WARNING, "Failed to manage stops", e);
            }
        }
    }

    // ====================== Utilities ======================

    static final class NamedThreadFactory implements ThreadFactory {
        private final String base;

        NamedThreadFactory(String base) {
            this.base = base;
        }

        @Override
        public Thread newThread(Runnable r) {
            Thread t = new Thread(r, base + "-" + UUID.randomUUID());
            t.setDaemon(true);
            return t;
        }
    }
}

/**
 * Simple Web Scraper for Sunny Hurghada (Soma Bay properties)
 *
 * Description:
 * - Crawls listing pages for Soma Bay properties on the Sunny Hurghada website.
 * - Extracts property detail URLs.
 * - Visits each property page to extract price and description (with multiple fallbacks).
 * - Respects robots.txt when available.
 * - Handles pagination where possible.
 * - Outputs JSONL data to a file and stdout.
 *
 * Requirements:
 * - Node.js 18+ (for global fetch and AbortController)
 * - npm install cheerio robots-parser
 *
 * Example usage:
 *   node scraper.js --start https://sunnyhurghada.com/area/soma-bay/ --maxPages=5 --concurrency=3 --out=soma-bay.jsonl
 *
 * Notes:
 * - Always verify and comply with the target site's Terms of Service and robots.txt.
 * - Consider adding delays between requests and limit concurrency to be polite.
 */

'use strict';

const fs = require('fs');
const fsp = require('fs/promises');
const path = require('path');
const { setTimeout: delay } = require('timers/promises');
const cheerio = require('cheerio');
const robotsParser = require('robots-parser');

// ----------------------- Configuration -----------------------

const DEFAULT_USER_AGENT = 'Mozilla/5.0 (compatible; SunnyHurghadaScraper/1.0; +https://example.com/bot)';
const DEFAULT_CONCURRENCY = 3;
const DEFAULT_MAX_PAGES = 5;
const DEFAULT_TIMEOUT_MS = 20000;
const DEFAULT_DELAY_MS = [600, 1200]; // min/max delay between requests (ms)
const ALLOWED_CONTENT_TYPES = ['text/html', 'application/xhtml+xml'];

// ----------------------- Utilities ---------------------------

/**
 * Simple CLI args parser (no external deps)
 */
function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    let arg = argv[i];
    if (!arg.startsWith('--')) continue;
    arg = arg.slice(2);
    const [key, ...rest] = arg.split('=');
    const value = rest.length ? rest.join('=') : true;
    args[key] = value;
  }
  return args;
}

/**
 * Normalize and ensure absolute URL.
 */
function toAbsoluteUrl(base, href) {
  try {
    return new URL(href, base).toString();
  } catch {
    return null;
  }
}

/**
 * Returns the origin (protocol + host + port) of a URL.
 */
function getOrigin(u) {
  try {
    const url = new URL(u);
    return url.origin;
  } catch {
    return null;
  }
}

/**
 * Sleep for a random amount between min and max milliseconds.
 */
async function randomDelay([min, max]) {
  const ms = Math.floor(Math.random() * (max - min + 1)) + min;
  await delay(ms);
}

/**
 * Ensures the content-type header is an allowed HTML type.
 */
function isHtmlResponse(contentType) {
  if (!contentType) return false;
  const lower = contentType.toLowerCase();
  return ALLOWED_CONTENT_TYPES.some((t) => lower.includes(t));
}

/**
 * Sanitize text content by trimming and collapsing whitespace.
 */
function sanitizeText(s) {
  if (!s || typeof s !== 'string') return '';
  return s.replace(/\s+/g, ' ').trim();
}

/**
 * Extract price and currency from a text string using heuristics.
 * Supports common currency symbols and codes (EGP, USD, EUR).
 */
function extractPriceFromText(text) {
  if (!text) return null;

  const t = text.replace(/[, ]+/g, ' ').trim();

  // Common patterns, tries to capture currency and number
  const patterns = [
    // E.g., "EGP 3,000,000" or "EGP 3000000"
    /(?:(EGP|USD|EUR|GBP)\s*)?([€$£]?)(\d[\d\s.,]*)/i,
    // E.g., "$ 300,000"
    /([€$£])\s*(\d[\d\s.,]*)/,
    // E.g., "Price: 1,500,000 EGP"
    /(\d[\d\s.,]*)\s*(EGP|USD|EUR|GBP)/i
  ];

  for (const re of patterns) {
    const m = t.match(re);
    if (m) {
      let currency = '';
      let amountStr = '';

      if (re === patterns[0]) {
        currency = (m[1] || m[2] || '').toUpperCase();
        amountStr = m[3] || '';
      } else if (re === patterns[1]) {
        currency = (m[1] || '').toUpperCase();
        amountStr = m[2] || '';
      } else {
        currency = (m[2] || '').toUpperCase();
        amountStr = m[1] || '';
      }

      // Map symbols to codes
      if (!currency) {
        if (m[2] === '€') currency = 'EUR';
        else if (m[2] === '$') currency = 'USD';
        else if (m[2] === '£') currency = 'GBP';
      } else if (currency === '€') currency = 'EUR';
      else if (currency === '$') currency = 'USD';
      else if (currency === '£') currency = 'GBP';

      // Normalize the amount into a number-like string (keep decimal dot)
      let normalized = amountStr.replace(/[\s,]+/g, '');
      // If number uses commas as decimal separator
      const commaDecimal = /^\d{1,3}(?:\.\d{3})*,\d+$/.test(amountStr);
      if (commaDecimal) {
        normalized = amountStr.replace(/\./g, '').replace(',', '.');
      }
      // Strip non-numeric except decimal dot
      normalized = normalized.replace(/[^\d.]/g, '');

      return {
        currency: currency || null,
        amountText: amountStr.trim(),
        amount: normalized ? Number(normalized) : null,
        raw: text.trim()
      };
    }
  }
  return null;
}

/**
 * Create a write stream for JSONL output with safe path handling.
 */
function createJsonlWriter(filePath) {
  const stream = fs.createWriteStream(filePath, { flags: 'a', encoding: 'utf8' });
  function write(obj) {
    try {
      stream.write(JSON.stringify(obj) + '\n');
    } catch (err) {
      console.error('Failed to write JSONL line:', err);
    }
  }
  function close() {
    return new Promise((resolve) => stream.end(resolve));
  }
  return { write, close };
}

/**
 * Retry wrapper with exponential backoff.
 */
async function withRetry(fn, { retries = 3, baseDelay = 500 } = {}) {
  let attempt = 0;
  let lastErr = null;
  while (attempt <= retries) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      const isLast = attempt === retries;
      if (isLast) break;
      const wait = baseDelay * Math.pow(2, attempt) + Math.floor(Math.random() * 200);
      await delay(wait);
      attempt++;
    }
  }
  throw lastErr;
}

// ----------------------- HTTP / Robots -----------------------

/**
 * Fetch a URL with timeout, user-agent, and basic headers.
 */
async function fetchHtml(url, { timeoutMs = DEFAULT_TIMEOUT_MS, userAgent = DEFAULT_USER_AGENT } = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'User-Agent': userAgent,
        'Accept': 'text/html,application/xhtml+xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.9',
        'Connection': 'keep-alive'
      },
      redirect: 'follow',
      signal: controller.signal
    });

    if (!res.ok) {
      const err = new Error(`HTTP ${res.status} for ${url}`);
      err.response = res;
      throw err;
    }
    const contentType = res.headers.get('content-type') || '';
    if (!isHtmlResponse(contentType)) {
      throw new Error(`Unexpected content-type "${contentType}" for ${url}`);
    }
    const text = await res.text();
    return { html: text, url: res.url, contentType };
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Load and parse robots.txt; if unavailable, return a permissive policy.
 */
async function loadRobots(origin, userAgent = DEFAULT_USER_AGENT) {
  const robotsUrl = `${origin}/robots.txt`;
  try {
    const { html: robotsTxt } = await withRetry(
      () => fetchHtml(robotsUrl, { userAgent }),
      { retries: 1, baseDelay: 400 }
    );
    const parser = robotsParser(robotsUrl, robotsTxt);
    return parser;
  } catch {
    // If robots.txt is missing or fetch fails, assume permissive behavior.
    return robotsParser(robotsUrl, '');
  }
}

/**
 * Checks whether scraping a given URL is allowed by robots.txt for the user agent.
 */
function isAllowedByRobots(robots, url, userAgent = DEFAULT_USER_AGENT) {
  try {
    return robots.isAllowed(url, userAgent) !== false;
  } catch {
    return true;
  }
}

// ----------------------- Parsing -----------------------------

/**
 * Parse listing page to extract:
 * - Property detail URLs
 * - Next page URL (for pagination)
 */
function parseListingPage(listingUrl, html) {
  const $ = cheerio.load(html);

  const detailUrls = new Set();

  // Heuristic selectors for property cards and detail links
  const linkSelectors = [
    'a.property-title',
    'a.property-link',
    '.property-item a',
    '.listing-item a',
    '.property-card a',
    '.entry-title a',
    'article a',
    '.elementor a',
    'a[href*="/property/"]',
    'a[href*="/properties/"]'
  ];

  for (const sel of linkSelectors) {
    $(sel).each((_, el) => {
      const href = $(el).attr('href');
      if (!href) return;
      const abs = toAbsoluteUrl(listingUrl, href);
      if (!abs) return;
      // Filter: Same site only
      const sameSite = getOrigin(abs) === getOrigin(listingUrl);
      if (!sameSite) return;
      // Heuristic: Likely a property detail page
      if (/\/(property|properties|listing|real-estate|apartment|villa|house)\//i.test(abs) || /\/\d{4}\/\d{2}\//.test(abs)) {
        detailUrls.add(abs.split('#')[0]);
      }
    });
  }

  // Pagination: attempt to find "next" page link
  let nextPage = null;
  const nextSelectors = [
    'a[rel="next"]',
    'a.next',
    '.pagination a.next',
    '.nav-links a.next',
    '.page-numbers a.next',
    '.page-numbers .next',
    'a[aria-label="Next"]',
    '.pagination a[rel="next"]'
  ];
  for (const sel of nextSelectors) {
    const el = $(sel).first();
    if (el && el.length) {
      const href = el.attr('href');
      if (href) {
        nextPage = toAbsoluteUrl(listingUrl, href);
        break;
      }
    }
  }

  // Fallback: look for page numbers and select the largest "current+1"
  if (!nextPage) {
    const candidates = [];
    $('a.page-numbers, .pagination a, .nav-links a').each((_, el) => {
      const href = $(el).attr('href');
      const txt = sanitizeText($(el).text());
      if (href && /^\d+$/.test(txt)) {
        candidates.push({ page: parseInt(txt, 10), href: toAbsoluteUrl(listingUrl, href) });
      }
    });
    if (candidates.length) {
      const max = candidates.sort((a, b) => a.page - b.page).pop();
      nextPage = max.href || null;
    }
  }

  return {
    detailUrls: Array.from(detailUrls),
    nextPage
  };
}

/**
 * Attempt to extract price and description from property detail page HTML.
 * Uses multiple strategies:
 * - JSON-LD (schema.org) parsing
 * - Common DOM selectors for price and description
 * - Heuristic text scanning
 */
function parsePropertyDetail(detailUrl, html) {
  const $ = cheerio.load(html);

  // Title
  let title =
    sanitizeText($('h1').first().text()) ||
    sanitizeText($('.entry-title').first().text()) ||
    sanitizeText($('title').first().text());

  // JSON-LD structured data
  let jsonLdData = [];
  $('script[type="application/ld+json"]').each((_, el) => {
    try {
      const raw = $(el).contents().text();
      if (!raw) return;
      const data = JSON.parse(raw);
      if (Array.isArray(data)) jsonLdData.push(...data);
      else jsonLdData.push(data);
    } catch {
      // ignore malformed JSON-LD
    }
  });

  let priceObj = null;
  let description = '';

  for (const node of jsonLdData) {
    const graph = node['@graph'] && Array.isArray(node['@graph']) ? node['@graph'] : [node];
    for (const item of graph) {
      const type = Array.isArray(item['@type']) ? item['@type'].join(',') : item['@type'];
      if (!type) continue;

      // RealEstateListing, Offer, Product, Article as fallbacks
      if (/RealEstateListing|Offer|Product|Article|WebPage/i.test(type)) {
        const offers = item.offers || item.offer;
        const price = item.price || item.priceSpecification?.price || offers?.price || offers?.priceSpecification?.price;
        const priceCurrency = item.priceCurrency || item.priceSpecification?.priceCurrency || offers?.priceCurrency || offers?.priceSpecification?.priceCurrency;
        const desc = item.description || item.text || item.headline || '';
        const parsedPrice = price ? extractPriceFromText(String(priceCurrency || '') + ' ' + String(price)) : null;
        if (!priceObj && parsedPrice) priceObj = parsedPrice;
        if (!description && desc) description = sanitizeText(desc);
      }
    }
  }

  // DOM selectors for price if JSON-LD not found
  if (!priceObj) {
    const priceSelectors = [
      '.property-price', '.price', '.listing-price', '.elementor-widget-container .price',
      '.offer-price', '.details .price', '.property__price', 'span.price', 'div.price'
    ];
    for (const sel of priceSelectors) {
      const txt = sanitizeText($(sel).first().text());
      if (txt && /\d/.test(txt)) {
        const p = extractPriceFromText(txt);
        if (p) {
          priceObj = p;
          break;
        }
      }
    }
  }

  // Try also meta tags for price (less common but sometimes used)
  if (!priceObj) {
    const metaPrice = $('meta[itemprop="price"]').attr('content') || $('meta[property="product:price:amount"]').attr('content');
    const metaCurrency = $('meta[itemprop="priceCurrency"]').attr('content') || $('meta[property="product:price:currency"]').attr('content');
    if (metaPrice) {
      const p = extractPriceFromText(`${metaCurrency || ''} ${metaPrice}`);
      if (p) priceObj = p;
    }
  }

  // DOM selectors for description
  if (!description) {
    const descSelectors = [
      '.property-content', '.property-description', '.description', '.entry-content',
      'article .content', '.post-content', '.elementor-widget-text-editor', '.single-content',
      'section.description', '[itemprop="description"]'
    ];
    for (const sel of descSelectors) {
      const txt = sanitizeText($(sel).first().text());
      if (txt && txt.length > 60) {
        description = txt;
        break;
      }
    }
  }

  // Fallback: collect paragraphs
  if (!description) {
    const paragraphs = [];
    $('p').each((_, el) => {
      const t = sanitizeText($(el).text());
      if (t && t.length > 40) paragraphs.push(t);
    });
    if (paragraphs.length) {
      description = sanitizeText(paragraphs.slice(0, 5).join(' '));
    }
  }

  // Price fallback: scan entire text if necessary
  if (!priceObj) {
    const bodyText = sanitizeText($('body').text());
    const p = extractPriceFromText(bodyText);
    if (p) priceObj = p;
  }

  return {
    title: title || null,
    price: priceObj || null,
    description: description || null
  };
}

// ----------------------- Crawler -----------------------------

class Crawler {
  constructor(options) {
    this.startUrl = options.startUrl;
    this.maxPages = options.maxPages ?? DEFAULT_MAX_PAGES;
    this.concurrency = options.concurrency ?? DEFAULT_CONCURRENCY;
    this.userAgent = options.userAgent ?? DEFAULT_USER_AGENT;
    this.delayRange = options.delayRange ?? DEFAULT_DELAY_MS;
    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.outFile = options.outFile ?? path.resolve(process.cwd(), 'soma-bay-properties.jsonl');

    this.origin = getOrigin(this.startUrl);
    this.robots = null;

    this.visited = new Set();
    this.detailVisited = new Set();
    this.queue = [];
    this.detailQueue = [];
    this.active = 0;

    this.writer = createJsonlWriter(this.outFile);
  }

  async init() {
    if (!this.origin) {
      throw new Error('Invalid start URL, cannot determine site origin.');
    }
    this.robots = await loadRobots(this.origin, this.userAgent);
  }

  enqueueListing(url) {
    if (this.visited.has(url)) return false;
    this.queue.push(url);
    return true;
  }

  enqueueDetail(url) {
    if (this.detailVisited.has(url)) return false;
    this.detailQueue.push(url);
    return true;
  }

  async run() {
    await this.init();

    if (!isAllowedByRobots(this.robots, this.startUrl, this.userAgent)) {
      throw new Error(`Blocked by robots.txt: ${this.startUrl}`);
    }

    this.enqueueListing(this.startUrl);

    let pagesProcessed = 0;

    while (this.queue.length > 0 && pagesProcessed < this.maxPages) {
      const listingUrl = this.queue.shift();
      if (!listingUrl || this.visited.has(listingUrl)) continue;

      this.visited.add(listingUrl);

      try {
        await randomDelay(this.delayRange);
        const { html, url: finalUrl } = await withRetry(
          () => fetchHtml(listingUrl, { timeoutMs: this.timeoutMs, userAgent: this.userAgent }),
          { retries: 2, baseDelay: 600 }
        );

        const { detailUrls, nextPage } = parseListingPage(finalUrl, html);

        // Enqueue details (respect robots)
        for (const d of detailUrls) {
          if (!isAllowedByRobots(this.robots, d, this.userAgent)) continue;
          this.enqueueDetail(d);
        }

        // Enqueue pagination if allowed
        if (nextPage && !this.visited.has(nextPage) && isAllowedByRobots(this.robots, nextPage, this.userAgent)) {
          this.enqueueListing(nextPage);
        }

        pagesProcessed++;
      } catch (err) {
        console.error(`Failed to process listing page: ${listingUrl}`, err.message || err);
      }
    }

    // Process detail pages with limited concurrency
    await this.processDetails();

    await this.writer.close();
  }

  async processDetails() {
    const limit = this.concurrency;
    const workers = Array.from({ length: limit }, () => this.detailWorker());
    await Promise.all(workers);
  }

  async detailWorker() {
    while (true) {
      const url = this.detailQueue.shift();
      if (!url) break;
      if (this.detailVisited.has(url)) continue;

      this.detailVisited.add(url);

      try {
        await randomDelay(this.delayRange);

        if (!isAllowedByRobots(this.robots, url, this.userAgent)) {
          console.warn(`Robots disallowed, skipping: ${url}`);
          continue;
        }

        const { html, url: finalUrl } = await withRetry(
          () => fetchHtml(url, { timeoutMs: this.timeoutMs, userAgent: this.userAgent }),
          { retries: 2, baseDelay: 600 }
        );

        const data = parsePropertyDetail(finalUrl, html);
        const record = {
          url: finalUrl,
          title: data.title,
          price: data.price, // { currency, amountText, amount, raw }
          description: data.description,
          scrapedAt: new Date().toISOString()
        };

        // Basic validation: ensure at least price or description exists
        if (!record.price && !record.description) {
          console.warn(`No price/description found for: ${finalUrl}`);
        }

        // Output to stdout and file
        console.log(JSON.stringify(record));
        this.writer.write(record);
      } catch (err) {
        console.error(`Failed to process detail page: ${url}`, err.message || err);
      }
    }
  }
}

// ----------------------- Main -------------------------------

(async function main() {
  const args = parseArgs(process.argv);

  const start = args.start || args.url || '';
  if (!start) {
    console.error('Usage: node scraper.js --start <SomaBayListingURL> [--maxPages=5] [--concurrency=3] [--out=output.jsonl]');
    process.exit(1);
  }

  const options = {
    startUrl: start,
    maxPages: Number(args.maxPages || DEFAULT_MAX_PAGES),
    concurrency: Number(args.concurrency || DEFAULT_CONCURRENCY),
    userAgent: args.userAgent || DEFAULT_USER_AGENT,
    outFile: path.resolve(process.cwd(), args.out || 'soma-bay-properties.jsonl'),
    timeoutMs: Number(args.timeoutMs || DEFAULT_TIMEOUT_MS),
    delayRange: DEFAULT_DELAY_MS
  };

  // Ensure output directory exists
  try {
    await fsp.mkdir(path.dirname(options.outFile), { recursive: true });
  } catch {
    // ignore
  }

  try {
    const crawler = new Crawler(options);
    await crawler.run();
    console.error('Scraping completed.');
  } catch (err) {
    console.error('Fatal error:', err.message || err);
    process.exit(2);
  }
})();

/**
 * Display car models and prices from the current Cid Autos website page.
 *
 * How to use:
 * - Open the Cid Autos inventory/listings page in your browser.
 * - Paste this code into the browser devtools console and run:
 *     displayCidAutosModelsAndPrices();
 *
 * What it does:
 * - Heuristically finds listing cards on the page.
 * - Extracts model/title, price, and detail link (if available).
 * - Displays results in a floating, sortable-like table with options to Copy/Download/Close.
 *
 * Notes:
 * - This uses best-effort DOM heuristics since the exact site structure may vary.
 * - If you know the exact CSS selectors for cards/title/price, pass them via the options argument.
 * - This code runs entirely in the browser against the live DOM (no external requests).
 */
(function () {
  "use strict";

  /**
   * Main entry point: scrapes and displays models + prices.
   * @param {Object} [options]
   * @param {string[]} [options.cardSelectors] - CSS selectors to detect listing cards
   * @param {string[]} [options.titleSelectors] - CSS selectors to detect title/model inside a card
   * @param {string[]} [options.priceSelectors] - CSS selectors to detect price inside a card
   * @param {boolean} [options.includeOutOfView=false] - Include cards not currently visible
   * @param {boolean} [options.debug=false] - Logs additional debugging information
   */
  function displayCidAutosModelsAndPrices(options = {}) {
    const config = normalizeOptions(options);

    try {
      const cards = findListingCards(config);

      const items = [];
      for (const card of cards) {
        const item = extractItemFromCard(card, config);
        if (item) {
          items.push(item);
        }
      }

      const deduped = deduplicateItems(items);

      if (config.debug) {
        console.debug("[CidAutos] Found cards:", cards.length);
        console.debug("[CidAutos] Extracted items:", items);
        console.debug("[CidAutos] Deduped items:", deduped);
      }

      if (deduped.length === 0) {
        notify("No car listings with prices were detected on this page. Try scrolling or navigating to the inventory page.", "warn");
        return;
      }

      showOverlay(deduped);
    } catch (err) {
      console.error("[CidAutos] Error:", err);
      notify(`Unexpected error: ${err && err.message ? err.message : String(err)}`, "error");
    }
  }

  // -----------------------------
  // Configuration and Utilities
  // -----------------------------

  function normalizeOptions(options) {
    const defaults = {
      cardSelectors: [
        // Common inventory/listing card patterns
        ".vehicle-card",
        ".inventory-card",
        ".inventory-item",
        ".listing",
        ".result-row",
        ".vehicle",
        ".car-card",
        "article.vehicle",
        "article.listing",
        "li.inventory-item",
        "div[class*=vehicle-card]",
        "div[class*=inventory-card]",
        "div[class*=listing]",
        "div[class*=result]",
        "div[class*=vehicle]",
        "article",
        "li",
      ],
      titleSelectors: [
        ".vehicle-title",
        ".title",
        ".model",
        ".heading",
        "h1",
        "h2",
        "h3",
        "a[title]",
        "a",
      ],
      priceSelectors: [
        ".price",
        ".vehicle-price",
        ".pricing",
        "[class*=price]",
        "[data-testid*=price]",
        "span",
        "div",
        "p",
      ],
      includeOutOfView: false,
      debug: false,
    };

    const cfg = Object.assign({}, defaults, options);

    // Compile regexes once
    cfg._priceRegex = /\$\s*[0-9]{1,3}(?:[, ]?[0-9]{3})*(?:\.[0-9]{2})?/; // $12,345.67
    cfg._altPriceTerms = [
      "price",
      "msrp",
      "sale",
      "special",
      "internet price",
      "our price",
      "as low as",
    ];
    cfg._invalidTitleTerms = [
      "price",
      "call",
      "contact",
      "finance",
      "payment",
      "mileage",
      "stock",
      "vin",
    ];

    return cfg;
  }

  function getText(el) {
    return (el && (el.textContent || "").trim()) || "";
  }

  function isVisible(el) {
    if (!el) return false;
    const style = window.getComputedStyle(el);
    if (style.display === "none" || style.visibility === "hidden" || Number(style.opacity) === 0) {
      return false;
    }
    const rect = el.getBoundingClientRect();
    // Consider visible if it has dimensions and intersects viewport (loosely)
    const hasSize = (rect.width > 0 && rect.height > 0);
    const inViewport = rect.bottom >= 0 && rect.right >= 0 && rect.top <= (window.innerHeight || 0) && rect.left <= (window.innerWidth || 0);
    return hasSize && inViewport;
  }

  function normalizeWhitespace(str) {
    return (str || "").replace(/\s+/g, " ").trim();
  }

  function cleanTitle(str) {
    let s = normalizeWhitespace(str);
    // Remove price-like tokens accidentally included
    s = s.replace(/\$\s*[0-9]{1,3}(?:[, ]?[0-9]{3})*(?:\.[0-9]{2})?/g, "");
    // Remove mileage and stock tokens commonly cluttering titles
    s = s.replace(/\b(Stock|VIN|Mileage|Miles)\b[^|]*\|?/gi, "");
    return normalizeWhitespace(s);
  }

  function extractPriceFromText(text, cfg) {
    if (!text) return null;
    const match = text.match(cfg._priceRegex);
    if (match) {
      // Normalize to $XX,XXX.xx formatting
      const raw = match[0];
      const digits = raw.replace(/[^\d.]/g, "");
      if (!digits) return raw.trim();
      const num = Number(digits);
      if (!isNaN(num) && isFinite(num)) {
        // Keep original if it already contains formatting (safer)
        return raw.trim();
      }
      return "$" + digits;
    }
    return null;
  }

  function likelyPriceNode(el, cfg) {
    if (!el) return false;
    const txt = getText(el).toLowerCase();
    const hasDollar = cfg._priceRegex.test(txt);
    const hasAltTerm = cfg._altPriceTerms.some(term => txt.includes(term));
    return hasDollar || hasAltTerm;
  }

  function likelyTitleText(text, cfg) {
    if (!text) return false;
    const t = text.toLowerCase();
    if (t.length < 3) return false;
    if (cfg._priceRegex.test(t)) return false; // avoid price as title
    if (cfg._invalidTitleTerms.some(term => t.includes(term))) return false;
    // Heuristic: a title often has letters/numbers and spaces
    return /[a-z0-9]/i.test(t);
  }

  // -----------------------------
  // Card Detection and Extraction
  // -----------------------------

  function findListingCards(cfg) {
    const seen = new Set();
    const cards = [];

    const pushUnique = (el) => {
      if (!el || !(el instanceof Element)) return;
      const key = getDomPath(el);
      if (!seen.has(key)) {
        seen.add(key);
        cards.push(el);
      }
    };

    // 1) Try known card selectors
    for (const sel of cfg.cardSelectors) {
      const nodes = document.querySelectorAll(sel);
      for (const el of nodes) {
        // Filter to cards that contain some price-like element
        if (!containsPrice(el, cfg)) continue;
        if (!cfg.includeOutOfView && !isVisible(el)) continue;
        pushUnique(el);
      }
    }

    // 2) Fallback: find price nodes and walk up to a reasonable container
    if (cards.length === 0) {
      const allNodes = document.querySelectorAll("body *");
      for (const el of allNodes) {
        if (!likelyPriceNode(el, cfg)) continue;
        const card = ascendToCard(el, cfg);
        if (card) {
          if (!cfg.includeOutOfView && !isVisible(card)) continue;
          pushUnique(card);
        }
      }
    }

    return cards;
  }

  function containsPrice(root, cfg) {
    if (!root || !(root instanceof Element)) return false;
    // Quick checks via known selectors like .price or terms
    for (const sel of cfg.priceSelectors) {
      const el = root.querySelector(sel);
      if (el && likelyPriceNode(el, cfg)) return true;
    }
    // If not found, scan limited descendants for performance
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, null);
    let count = 0;
    while (walker.nextNode() && count < 250) {
      count++;
      const el = walker.currentNode;
      if (likelyPriceNode(el, cfg)) return true;
    }
    return false;
  }

  function ascendToCard(priceNode, cfg) {
    let el = priceNode;
    let steps = 0;
    while (el && steps < 6) {
      // A "card" usually has a title-like element and not too many nested cards
      const title = findTitleIn(el, cfg);
      if (title) return el;
      el = el.parentElement;
      steps++;
    }
    return null;
  }

  function findTitleIn(root, cfg) {
    // Try selectors first
    for (const sel of cfg.titleSelectors) {
      const cand = root.querySelector(sel);
      const txt = cleanTitle(getText(cand));
      if (likelyTitleText(txt, cfg)) return cand;
    }
    // Fallback: find the most "prominent" heading text
    const headings = root.querySelectorAll("h1, h2, h3, h4, a");
    for (const h of headings) {
      const txt = cleanTitle(getText(h));
      if (likelyTitleText(txt, cfg)) return h;
    }
    return null;
  }

  function extractItemFromCard(card, cfg) {
    if (!card) return null;

    // Title/Model
    let titleEl = null;
    for (const sel of cfg.titleSelectors) {
      const el = card.querySelector(sel);
      if (el) {
        const txt = cleanTitle(getText(el));
        if (likelyTitleText(txt, cfg)) {
          titleEl = el;
          break;
        }
      }
    }
    if (!titleEl) {
      // Try headings or anchors generally
      const guess = findTitleIn(card, cfg);
      if (guess) titleEl = guess;
    }

    const title = titleEl ? cleanTitle(getText(titleEl)) : "";

    // Price
    let price = null;
    // First pass: use price selectors
    for (const sel of cfg.priceSelectors) {
      const el = card.querySelector(sel);
      if (!el) continue;
      const p = extractPriceFromText(getText(el), cfg);
      if (p) {
        price = p;
        break;
      }
    }
    // Second pass: scan limited descendants
    if (!price) {
      const walker = document.createTreeWalker(card, NodeFilter.SHOW_ELEMENT, null);
      let count = 0;
      while (walker.nextNode() && count < 300) {
        count++;
        const el = walker.currentNode;
        const p = extractPriceFromText(getText(el), cfg);
        if (p) {
          price = p;
          break;
        }
      }
    }

    // Link (if available)
    let link = "";
    const linkCand = card.querySelector("a[href]");
    if (linkCand && linkCand.href && !linkCand.href.endsWith("#")) {
      link = linkCand.href;
    }

    // Validate
    const hasReasonableTitle = title && title.length >= 3;
    const hasPrice = !!price;

    if (!hasReasonableTitle && !hasPrice) {
      return null;
    }

    return {
      title: hasReasonableTitle ? title : "Unknown Model",
      price: hasPrice ? price : "N/A",
      link,
    };
  }

  function deduplicateItems(items) {
    const seen = new Set();
    const out = [];
    for (const it of items) {
      const key = [it.title.toLowerCase(), it.price.toLowerCase(), it.link.toLowerCase()].join("|");
      if (!seen.has(key)) {
        seen.add(key);
        out.push(it);
      }
    }
    // Sort by title then by price
    out.sort((a, b) => {
      const t = a.title.localeCompare(b.title, undefined, { numeric: true, sensitivity: "base" });
      if (t !== 0) return t;
      return a.price.localeCompare(b.price, undefined, { numeric: true, sensitivity: "base" });
    });
    return out;
  }

  function getDomPath(el) {
    if (!el) return "";
    const parts = [];
    let current = el;
    while (current && current.nodeType === 1) {
      let part = current.nodeName.toLowerCase();
      if (current.id) part += "#" + current.id;
      // Add nth-of-type to reduce collisions
      const parent = current.parentNode;
      if (parent) {
        const siblings = Array.from(parent.children).filter(c => c.nodeName === current.nodeName);
        if (siblings.length > 1) {
          const index = siblings.indexOf(current);
          part += `:nth-of-type(${index + 1})`;
        }
      }
      parts.unshift(part);
      if (parts.length > 8) break; // limit path length
      current = current.parentElement;
    }
    return parts.join(">");
  }

  // -----------------------------
  // UI Overlay
  // -----------------------------

  function showOverlay(items) {
    removeExistingOverlay();

    const root = document.createElement("div");
    root.id = "cid-autos-inventory-overlay";
    root.setAttribute("role", "dialog");
    root.setAttribute("aria-modal", "true");
    root.style.position = "fixed";
    root.style.inset = "40px";
    root.style.background = "white";
    root.style.border = "1px solid #e5e7eb";
    root.style.borderRadius = "8px";
    root.style.boxShadow = "0 10px 25px rgba(0,0,0,0.15)";
    root.style.zIndex = String(10_000_000);
    root.style.display = "flex";
    root.style.flexDirection = "column";
    root.style.fontFamily = "system-ui, -apple-system, Segoe UI, Roboto, sans-serif";
    root.style.overflow = "hidden";

    const header = document.createElement("div");
    header.style.padding = "12px 16px";
    header.style.background = "#111827";
    header.style.color = "#fff";
    header.style.display = "flex";
    header.style.alignItems = "center";
    header.style.justifyContent = "space-between";

    const title = document.createElement("div");
    title.textContent = `Cid Autos Inventory (${items.length})`;
    title.style.fontWeight = "600";
    title.style.fontSize = "16px";
    header.appendChild(title);

    const actions = document.createElement("div");
    actions.style.display = "flex";
    actions.style.gap = "8px";

    const btnCopy = createButton("Copy CSV", () => copyCSV(items));
    const btnDownload = createButton("Download CSV", () => downloadCSV(items));
    const btnClose = createButton("Close", removeExistingOverlay);
    btnClose.style.background = "#ef4444";
    btnClose.style.borderColor = "#ef4444";

    actions.appendChild(btnCopy);
    actions.appendChild(btnDownload);
    actions.appendChild(btnClose);
    header.appendChild(actions);

    const body = document.createElement("div");
    body.style.flex = "1 1 auto";
    body.style.overflow = "auto";
    body.style.padding = "12px 16px";
    body.style.background = "#f9fafb";

    const table = document.createElement("table");
    table.style.width = "100%";
    table.style.borderCollapse = "collapse";
    table.style.background = "#fff";
    table.style.border = "1px solid #e5e7eb";

    const thead = document.createElement("thead");
    const headRow = document.createElement("tr");
    ["Model", "Price", "Link"].forEach((label) => {
      const th = document.createElement("th");
      th.textContent = label;
      th.style.textAlign = "left";
      th.style.padding = "10px 12px";
      th.style.borderBottom = "1px solid #e5e7eb";
      th.style.background = "#f3f4f6";
      th.style.fontWeight = "600";
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);

    const tbody = document.createElement("tbody");
    for (const item of items) {
      const tr = document.createElement("tr");

      const tdModel = document.createElement("td");
      tdModel.textContent = item.title;
      tdModel.style.padding = "10px 12px";
      tdModel.style.borderBottom = "1px solid #f3f4f6";

      const tdPrice = document.createElement("td");
      tdPrice.textContent = item.price;
      tdPrice.style.padding = "10px 12px";
      tdPrice.style.borderBottom = "1px solid #f3f4f6";
      tdPrice.style.whiteSpace = "nowrap";

      const tdLink = document.createElement("td");
      tdLink.style.padding = "10px 12px";
      tdLink.style.borderBottom = "1px solid #f3f4f6";
      if (item.link) {
        const a = document.createElement("a");
        a.href = item.link;
        a.textContent = "View";
        a.target = "_blank";
        a.rel = "noopener";
        a.style.color = "#2563eb";
        a.style.textDecoration = "none";
        a.addEventListener("mouseover", () => (a.style.textDecoration = "underline"));
        a.addEventListener("mouseout", () => (a.style.textDecoration = "none"));
        tdLink.appendChild(a);
      } else {
        tdLink.textContent = "—";
        tdLink.style.color = "#6b7280";
      }

      tr.appendChild(tdModel);
      tr.appendChild(tdPrice);
      tr.appendChild(tdLink);

      tbody.appendChild(tr);
    }

    table.appendChild(thead);
    table.appendChild(tbody);

    body.appendChild(table);

    const footer = document.createElement("div");
    footer.style.padding = "8px 16px";
    footer.style.background = "#f9fafb";
    footer.style.color = "#6b7280";
    footer.style.fontSize = "12px";
    footer.textContent = "Tip: Scroll the page to load more items, then run the function again if the site uses infinite scroll.";

    root.appendChild(header);
    root.appendChild(body);
    root.appendChild(footer);

    document.body.appendChild(root);
  }

  function createButton(label, onClick) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = label;
    btn.style.background = "#2563eb";
    btn.style.color = "#fff";
    btn.style.border = "1px solid #2563eb";
    btn.style.borderRadius = "6px";
    btn.style.padding = "8px 10px";
    btn.style.cursor = "pointer";
    btn.style.fontSize = "13px";
    btn.addEventListener("click", async () => {
      try {
        await onClick();
      } catch (e) {
        console.error("[CidAutos] Button action error:", e);
        notify(`Action failed: ${e && e.message ? e.message : String(e)}`, "error");
      }
    });
    btn.addEventListener("mouseover", () => (btn.style.opacity = "0.9"));
    btn.addEventListener("mouseout", () => (btn.style.opacity = "1"));
    return btn;
  }

  function removeExistingOverlay() {
    const existing = document.getElementById("cid-autos-inventory-overlay");
    if (existing && existing.parentNode) {
      existing.parentNode.removeChild(existing);
    }
  }

  function itemsToCSV(items) {
    const rows = [["Model", "Price", "Link"]];
    for (const it of items) {
      rows.push([it.title, it.price, it.link || ""]);
    }
    return rows
      .map((r) =>
        r
          .map((field) => {
            const s = String(field ?? "");
            if (/[",\n]/.test(s)) {
              return `"${s.replace(/"/g, '""')}"`;
            }
            return s;
          })
          .join(",")
      )
      .join("\n");
  }

  async function copyCSV(items) {
    const csv = itemsToCSV(items);
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(csv);
      notify("CSV copied to clipboard.", "success");
    } else {
      // Fallback: use a hidden textarea
      const ta = document.createElement("textarea");
      ta.value = csv;
      ta.style.position = "fixed";
      ta.style.left = "-10000px";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
        notify("CSV copied to clipboard.", "success");
      } finally {
        document.body.removeChild(ta);
      }
    }
  }

  function downloadCSV(items) {
    const csv = itemsToCSV(items);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const date = new Date();
    const iso = date.toISOString().replace(/[:.]/g, "-");
    a.download = `cid-autos-inventory-${iso}.csv`;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 0);
  }

  function notify(message, type = "info") {
    // Lightweight toast
    const toast = document.createElement("div");
    toast.textContent = message;
    toast.style.position = "fixed";
    toast.style.bottom = "20px";
    toast.style.right = "20px";
    toast.style.zIndex = String(10_000_001);
    toast.style.padding = "10px 14px";
    toast.style.borderRadius = "6px";
    toast.style.color = "#fff";
    toast.style.fontSize = "13px";
    toast.style.boxShadow = "0 4px 18px rgba(0,0,0,0.15)";
    toast.style.background =
      type === "success" ? "#16a34a" :
      type === "warn" ? "#f59e0b" :
      type === "error" ? "#ef4444" :
      "#374151";

    document.body.appendChild(toast);
    setTimeout(() => {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
    }, 3000);
  }

  // Expose to global scope
  window.displayCidAutosModelsAndPrices = displayCidAutosModelsAndPrices;
})();

